pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = it / cap; // item fill fraction
    let pr_norm = pr / cap;

    // Base: penalize leftover space, quadratically (dead space is super-linearly bad)
    let mut score = pr_norm * pr_norm * cap;

    // Smooth coupling: late in the stream, tight fits matter more
    let tightness = 1.0 - pr_norm; // how full the bin becomes
    let progress_coupling = progress * tightness * tightness;
    score -= 12.0 * progress_coupling * cap * fill;

    // Reward near-perfect fits with smooth bell-shaped term
    let perfect = (pr_norm * cap - 0.0).exp() * (-pr_norm * pr_norm * 8.0).exp();
    score -= 10.0 * perfect * (0.3 + 0.7 * progress);

    // Lookahead: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr - nx).max(0.0) / cap;
        let match_quality = 1.0 - ((pr - nx) / cap).abs();
        score -= 6.0 * usable * (0.5 + 0.5 * match_quality);
        // Penalize residuals that almost-but-not-quite fit the next item
        let gap = pr - nx;
        if gap > 0.0 && gap < 10.0 {
            score += 4.0 * (1.0 - gap / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.4 + 0.6 * progress);
    }

    // Mild penalty for spreading across many open bins vs. consolidating
    let mean_gap = (mean_residual - pr).abs() / cap;
    score += 2.0 * mean_gap * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make empty bins less attractive unless item is large or fits are scarce
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        let big_item = fill * fill;
        score += 8.0 * (1.0 - big_item) * (1.0 - scarcity) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps of 1..=9 are nearly unusable (min item is small
    // but rare); heavily penalize creating them, reward near-perfect fits.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        score -= 100.0; // perfect fill: best possible outcome
    }

    // Tight fit reward: item occupies most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 25.0 * fill_ratio;
    } else if fill_ratio < 0.3 {
        // Placing a small item into a large residual wastes the bin's flexibility.
        score += 20.0 * (0.3 - fill_ratio);
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 9 {
            score -= 45.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item would NOT fit here but would fit a fresh bin, keep this bin's space intact
    // only if the post-residual is still broadly usable; otherwise accept the placement.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 20 {
        score += 15.0; // creates dead space for the known future -> discourage
    }

    // Last-chance pressure: if only this bin fits, prefer using it over opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual != bin_capacity {
        score -= 6.0 + 0.5 * bin_pressure;
    } else {
        // New-bin candidate: only attractive when item is large relative to capacity
        // (hard to place later) or open-bin pressure is low.
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 40.0 * large_item - 10.0 * bin_pressure;
        // Penalize opening a new bin when the item would leave a very flexible residual
        // in an existing bin (mean_residual high means bins are mostly full anyway).
        if mean_residual > item_size as f64 * 1.5 {
            score += 25.0;
        }
    }

    // Slight preference for bins whose residual deviates most from mean (reduce variance).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // future item (min size 1, but practically < ~15) are near-useless.
    if post_residual < 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize small open-bin count pressure: prefer filling existing bins
    // when few bins are open; when many bins are open, allow spreading.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64 * 10.0);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // creates dead space relative to the known next item
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let base = 45.0;
        let poor_open = if mean_residual < item_size as f64 { 0.0 } else { -10.0 };
        score = base + poor_open - 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: overwhelmingly good.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Dead-space spike for tiny unusable gaps (sharpened threshold).
    if post_residual > 0 && post_residual < 8 {
        score += (8 - post_residual) as f64 * 10.0;
    } else if post_residual > 0 && post_residual < 14 {
        score += (14 - post_residual) as f64 * 2.5;
    }
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 12.0;
    }

    // Tightness reward.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 18.0;
    let fill_ratio = isz / bin_residual.max(1) as f64;
    score -= 3.5 * fill_ratio;

    // Lookahead on the next item, coupled with residual shape.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 750.0;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 270.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
            // Two-step chain: next item leaves a gap the item after could fill.
            if nx >= post_residual - nx.min(0.0).abs() as f64 { /* no-op guard */ }
            if pr - nx < 6.0 {
                score += 6.0; // would create a dead gap after next item
            }
        } else {
            score += 0.6 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
        }
    }

    // Last-chance pressure: only fitting bin, keep it alive.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count == 2 {
        score -= 4.0;
    }

    // Open-bin pressure.
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // New-bin candidate: only wins when no open bin fits or fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap);
        if fitting_bins_count == 0 {
            score -= 220.0;
        } else if fitting_bins_count == 1 {
            score -= 40.0; // strongly prefer using the single fitting bin
        }
        score -= 4.0 * progress;
        if fitting_bins_count > 0 && isz < 0.5 * cap {
            score += 28.0;
        }
        if pr > mean_residual {
            score += 10.0;
        }
        score -= open_bins_count as f64 * 0.8;
        // Late stream: opening fresh bins is cheaper than fragmenting.
        if progress > 0.75 && isz > 0.7 * cap {
            score -= 15.0;
        }
    }

    // Balance toward below-mean residual bins.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Reward near-exact fills that leave a gap matching the next item's class.
    if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual
        && next_item_size <= bin_residual {
        score += 3.0; // bin still usable by next item even if not by this exact gap
    }

    score
}

