pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let isz = item_size as f64;
    let mut score = pr;

    // Perfect fit: overwhelmingly good.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Dead-space spike for tiny unusable gaps (scaled by item size).
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 7.0;
    }
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 12.0;
    }

    // Tightness reward.
    let tightness = 1.0 - (pr / br.max(1.0));
    score -= tightness * 18.0;
    let fill_ratio = isz / br.max(1.0);
    score -= 3.5 * fill_ratio;

    // Lookahead on the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
            // Deviation of leftover from mean residual: keep future-friendly gaps.
            let dev = (fill_after_next - mean_residual).abs();
            score -= 12.0 * (1.0 - dev / cap).max(0.0);
            if fill_after_next == 0.0 {
                score -= 150.0;
            }
            if fill_after_next > 0.0 && fill_after_next < nx * 0.25 {
                score += 40.0;
            }
            if fill_after_next > 0.0 && fill_after_next >= nx * 0.25 && fill_after_next <= nx * 0.6 {
                score -= 18.0;
            }
            // Small leftover absorbable by a future small item: dead-space reduction.
            if fill_after_next > 0.0 && fill_after_next <= 8.0 {
                score -= 25.0;
            }
        } else {
            score += 0.6 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
            if next_item_size > bin_residual && br < nx * 0.5 {
                score += 30.0 * (1.0 - pr / cap);
            }
            // Penalize large dead space when many alternatives exist.
            if fitting_bins_count > 2 && br > nx * 0.75 {
                score += 15.0 * (br / cap);
            }
            // With few fitting bins, keep residual close to mean residual.
            if fitting_bins_count <= 2 {
                let dev = (pr - mean_residual).abs();
                score += 0.8 * dev;
            }
        }
    }

    // Last-chance pressure: only fitting bin, keep it alive.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // New-bin candidate: only wins when no open bin fits or fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        score -= 4.0 * progress;
        if fitting_bins_count > 0 && isz < 0.5 * cap {
            score += 28.0;
        }
        if pr > mean_residual {
            score += 10.0;
        }
        score -= open_bins_count as f64 * 0.8;
        // Avoid opening a bin for items that would leave a large stranded gap.
        if pr > 0.6 * cap && isz < 0.3 * cap {
            score += 15.0;
        }
        // Discourage opening a new bin when a decent existing fit exists.
        if fitting_bins_count > 0 && post_residual > 0 {
            let waste = pr;
            if waste <= cap * 0.15 {
                score += 120.0;
            } else {
                score += 20.0 + 0.3 * waste;
            }
        }
    }

    // Balance toward below-mean residual bins.
    if br < mean_residual {
        score -= 2.5;
    }

    score
}

