    score -= (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate: make an empty bin attractive only when the current
    // fit is bad (large post_residual) and there are already many bins.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64;
        score -= 12.0 + bad_fit * 0.25 + (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
