    if br < mean_residual {
        score -= 6.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: exact chain with next item is gold.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0;
        } else if post_residual >= next_item_size {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
            let dev = (fill_after_next - mean_residual).abs();
            score -= 12.0 * (1.0 - dev / cap).max(0.0);
