            score = item_size as f64 * 0.6 + 15.0;
            let progress = step_index as f64 / (total_items.max(1) as f64);
            // Late in the stream, dead space matters less; open a new bin
            // if the fresh residual is more useful than the mean residual
            // left in open bins (i.e., existing bins are fragmented).
            if (post_residual as f64) > mean_residual * (0.5 + progress) {
                score -= 20.0;
            }
