            if fitting_bins_count == 1 && post_residual > 0 {
                let worst_fit_waste = post_residual as f64;
                if worst_fit_waste > 40.0 {
                    score -= 15.0;
                }
            }
        }
    }

    // Mild pressure to consolidate: fewer open bins relative to progress
    // is good; penalize spreading across many bins.
    score += open_bins_count as f64 * 0.05;

    score
}

