        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 50.0; // fresh bin can chain the next item too
        }
    }

    // Mild normalization toward mean residual spread.
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // future item (min size 1, but practically < ~15) are near-useless.
    if post_residual < 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize small open-bin count pressure: prefer filling existing bins
    // when few bins are open; when many bins are open, allow spreading.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64 * 10.0);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // creates dead space relative to the known next item
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let base = 45.0;
        let poor_open = if mean_residual < item_size as f64 { 0.0 } else { -10.0 };
        score = base + poor_open - 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (low post_residual), but avoid unusable dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 800.0; // chain: perfect follow-up
        } else if next_item_size < post_residual {
            // next item fits: reward proportional to how well it fills post residual
            let fill_after_next = pr - nx;
            score -= 300.0 * (1.0 - fill_after_next / cap);
            // penalize leaving a large gap after both items
            score += 0.5 * fill_after_next;
        } else {
            // next item does NOT fit after placement: penalize moderately
            score += 60.0 + 0.3 * (nx - pr);
        }
    }

    // Compare post_residual to mean residual: closing a large-residual bin is good
    // if we reduce spread; penalize placements that make this bin an outlier.
    let dev = pr - mean_residual;
    score += 0.4 * dev.abs();

    // Last-chance bonus: only bin that fits the item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // Slight bias toward filling nearly-full bins early vs late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 50.0 * progress * (1.0 - pr / cap);

    // Mild penalty for opening a new bin when open bins could fit well.
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if item is large relative to capacity
        score += 30.0 * (1.0 - isz / cap);
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual quadratically.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin remains useful for the next item -> reward.
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space for the next item -> penalize proportionally.
            score += 0.35 * post_residual as f64
                * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: only tightness matters; slight bonus for exact fill.
        if post_residual == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else or global residuals are high.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin: grows with stream progress (fewer future
        // items to amortize the bin) and with number of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = score.max(score) + 55.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // If the item is small relative to capacity, opening a bin wastes space.
        score += 0.25 * (bin_capacity - item_size) as f64;
        // But if many bins fit the item poorly (crowded), a new bin is fine:
        // discount the penalty when mean residual is low.
        score -= 8.0 * mean_residual / bin_capacity as f64;
    } else {
        // Reusing an existing bin: reward bins whose residual is close to mean
        // (keeps residual spread compact) and penalize over-fragmentation.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.10 * dev;
        score -= 1.5 * open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
    }

    // Perfect-fill temptation: near-exact fits get a strong pull.
    if post_residual <= 2 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Late-stream consolidation: as the stream ends, prefer bins that get
    // emptied (post_residual small) to close them out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 24.0 * poly * (1.0 - progress);

    // Penalize large post-residual more as the stream matures
    score += 10.0 * norm_pr * norm_pr * progress;

    // Reward tight fits with smooth decay
    let tight = 1.0 - (pr / (1.0 + item_size as f64)).min(1.0);
    score -= 12.0 * tight * tight;

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward residual that could host the next item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (pr - next_item_size as f64 + 1.0).ln().max(0.0) / cap.ln();
    } else {
        score += pr; // last item: fully deplete bins
    }

    // Mild penalty for scattering across many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Diverge from mean residual: prefer bins deviating from the average
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band it falls into.
    // Perfect fits (0) are best; small dead space (<10) is heavily penalized.
    if post_residual == 0 {
        score -= 1000.0; // exact fit: always take it
    } else {
        // Integer division thresholds on post_residual (harmonic bands of C=100).
        let band = post_residual / 10; // 0..=10
        // Penalize tiny unusable remainders super-linearly.
        if band == 0 {
            score += 40.0; // 1..9 residual: near-dead space
        } else if band == 1 {
            score += 12.0; // 10..19: only fits smallest items
        } else if band == 2 {
            score -= 6.0;  // 20..29: useful pocket
        } else if band == 3 {
            score -= 10.0; // 30..39
        } else if band == 4 {
            score -= 14.0; // 40..49: very reusable
        } else {
            score -= 18.0; // >=50: half-empty, highly attractive
        }
    }

    // Modulo-5 arithmetic: residuals divisible by 5 pair well with typical sizes.
    if post_residual % 5 == 0 {
        score -= 5.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain placement: reward proportionally to how snug the chain is.
            let snug = (post_residual - next_item_size) as f64;
            score -= 15.0 - snug * 0.2;
        } else {
            // Next item won't chain here; slight penalty scaled by overshoot class.
            let over = (next_item_size - post_residual) as f64;
            score += (over / 10.0).floor() * 3.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it competitive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted as stream progresses / bins multiply.
        score = 55.0 + (open_bins_count as f64) * 0.5 - (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 8.0; // fresh bin can host the next item too
        }
    }

    // Mild pull toward bins whose residual deviates from the mean (prefer tightening outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item can use
    // (small gaps below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 {
        // Dead space: gap too small for even the smallest item (size 1..10 zone is rare,
        // but treat gaps < 10 as pure waste).
        if post_residual < 10 {
            score += 60.0;
        }
        // Gap unusable by the lookahead item but still usable in general: moderate penalty
        // that scales with how "wasted" the gap is relative to mean residual.
        else if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + 0.15 * (post_residual as f64);
        }
        // Perfect or near-perfect fit: strong reward.
        if post_residual == 0 {
            score -= 80.0;
        } else if post_residual <= 5 {
            score -= 30.0;
        }
    }

    // Tight-fit reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: prefer packing into existing bins when many are open,
    // but allow opening a new bin when few bins exist (early stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.5 + 2.0 * progress);

    // Last-chance bonus: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin (which would waste this bin's residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: the empty bin gets a baseline cost so it is only
    // chosen when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened slightly late in the stream
        // when mean residuals across open bins are high (poor packing so far).
        score = 100.0 - 0.2 * mean_residual - 10.0 * progress;
        // If the item is large and nothing else fits well, opening fresh is fine.
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        return score;
    }

    // Coupling with mean residual: prefer bins whose residual is below average
    // (i.e., the fullest bins), draining them to closure.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Lookahead synergy: if the post-residual exactly accommodates the next item,
    // reward reserving that space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large dead space (unusable residual).
    if post_residual < 10 {
        score -= 60.0; // near-perfect fit
    } else {
        score += (post_residual as f64) * 0.6;
    }

    // 2-step lookahead: reward when next item fits exactly / well into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let chain_gap = (post_residual as f64 - nxt).abs();
            score -= 45.0 - chain_gap * 1.5; // perfect chaining strongly rewarded
        } else {
            score += 15.0; // next item won't fit here: mild penalty
        }
    }

    // Relative-to-mean coupling: prefer bins whose post-residual is close to mean residual
    // (keeps residuals homogeneous and usable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.35;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score = (bin_capacity as f64) * 0.9
            + pressure * 2.0
            - (item_size as f64) * 0.2;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // big item coming: fresh bin useful
        }
    }

    // Late in stream: slightly prefer tightening existing bins over opening new ones.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= progress * 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * chain_quality;
    } else if next_item_size > 0 {
        // Next item won't chain here; mild penalty proportional to leftover dead space.
        score += 0.08 * post_residual as f64;
    }

    // Last chance: strongly prefer using the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize dumping items into bins with huge residuals when many bins are open
    // (fragmentation risk grows with open bin count).
    let frag = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 6.0 * frag * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Relative-to-mean adjustment: prefer bins below mean residual (more filled).
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when the item is large relative to typical
    // residuals or late in the stream; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_elsewhere = mean_residual - item_size as f64;
        let new_bin_bonus = -8.0 + 10.0 * progress + 0.15 * waste_elsewhere.max(0.0);
        score += new_bin_bonus.max(-15.0).min(20.0);
    }

    // Late-stream consolidation: favor filling existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fit), non-linearly penalized
    let mut score = post * (1.0 + norm_post * norm_post);

    // Smooth polynomial coupling with stream progress: late in the stream,
    // waste is more costly, so amplify the post_residual penalty.
    score += post * 2.0 * progress * (1.0 - progress + progress * progress);

    // Dead-space term: very small post-residuals are unusable; reward filling bins tightly
    let dead = (norm_post - 0.1).powi(2);
    score -= 30.0 * (-dead * 50.0).exp() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty proportional to leftover gap
        score += 4.0 * (next_item_size as f64 - post) / cap;
    }

    // Prefer bins with residuals below the mean (consolidate waste)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Slight preference for keeping fewer open bins early, more freedom later
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer-division buckets of capacity/10.
    // Low class = tight fit -> nonlinear reward, strongest for the lowest classes.
    let class = (post_residual / (bin_capacity / 10).max(1)).min(10);
    score -= (10 - class) as f64 * 3.0;

    // Lookahead coupling: reward bins whose residual can host the next item,
    // penalize dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += post_residual as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it
    // avoids opening a new bin -> strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): usually penalized,
    // but attractive when many open bins fit poorly or the next item is large.
    if bin_residual == bin_capacity {
        score += 6.0 + fitting_bins_count as f64 * 4.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
        if open_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Modulo harmonic penalty: awkward sub-bucket residuals (non-multiples of 10)
    // in the small-residual band are likely to become dead space.
    if post_residual % 10 != 0 && post_residual < 20 {
        score += 4.0;
    }

    // Mean-residual coupling: when open bins are generally full (low mean residual),
    // slightly favor reusing them over opening new bins.
    if bin_residual < bin_capacity {
        score -= (mean_residual / 20.0).min(3.0);
    }

    // Progress scaling: tighten decisions as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps of 1..=9 are nearly unusable (min item is small
    // but rare); heavily penalize creating them, reward near-perfect fits.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        score -= 100.0; // perfect fill: best possible outcome
    }

    // Tight fit reward: item occupies most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 25.0 * fill_ratio;
    } else if fill_ratio < 0.3 {
        // Placing a small item into a large residual wastes the bin's flexibility.
        score += 20.0 * (0.3 - fill_ratio);
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 9 {
            score -= 45.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item would NOT fit here but would fit a fresh bin, keep this bin's space intact
    // only if the post-residual is still broadly usable; otherwise accept the placement.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 20 {
        score += 15.0; // creates dead space for the known future -> discourage
    }

    // Last-chance pressure: if only this bin fits, prefer using it over opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual != bin_capacity {
        score -= 6.0 + 0.5 * bin_pressure;
    } else {
        // New-bin candidate: only attractive when item is large relative to capacity
        // (hard to place later) or open-bin pressure is low.
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 40.0 * large_item - 10.0 * bin_pressure;
        // Penalize opening a new bin when the item would leave a very flexible residual
        // in an existing bin (mean_residual high means bins are mostly full anyway).
        if mean_residual > item_size as f64 * 1.5 {
            score += 25.0;
        }
    }

    // Slight preference for bins whose residual deviates most from mean (reduce variance).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    }

    // Aggressive 2-step lookahead: perfect chaining (next item exactly fills
    // what this placement leaves behind) is the ideal outcome.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves further waste: penalize by the gap.
            let gap = (post_residual - next_item_size) as f64;
            score -= 80.0 - gap * 1.5;
        } else {
            // Next item cannot use this bin's leftover: leftover becomes dead
            // space; penalize proportionally to how unusable it is.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.2;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average waste is good (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when the item fits terribly
    // everywhere (large waste would be created) or late in the stream.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously.
        score += 120.0;
        // If the item would leave a big awkward remainder in existing bins,
        // a fresh bin becomes competitive.
        let waste_elsewhere = mean_residual - item_size as f64;
        if waste_elsewhere > 40.0 {
            score -= waste_elsewhere * 1.5;
        }
        // Late in the stream, avoid opening bins that will stay mostly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 80.0;
        // A fresh bin can also host the next item perfectly.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0;
        }
    }

    // Mild preference for filling bins that are already quite full.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Scale by number of open bins: with many open bins, consolidation matters.
    score *= 1.0 + (open_bins_count as f64).sqrt() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space non-linearly: small post-residuals are the most valuable.
    if post_residual > 0 {
        let pr = post_residual as f64;
