    // Exact-fit shaping relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // Post-residual too small for next item: dead-space penalty grows
            // with how close it is to being useless.
            score += 8.0;
        }
        // If the next item fits perfectly with this one, big reward.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Global state coupling: when many bins are open, prefer consolidation
    // (avoid opening new bins); when few are open, new bins are cheaper.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus pressure-dependent penalty,
