    // Small penalty for leaving residuals in the awkward 1..=10 range
    // (unusable by typical minimum item sizes).
    if post_residual >= 1 && post_residual <= 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Penalize waste more sharply as stream progresses
    score += 30.0 * progress * norm_pr * norm_pr;

    // Reward tight fits (small post residual) with smooth cubic decay
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap)) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 8.0 * progress * norm_pr;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Mild preference for consolidating among many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Deviation from mean residual: prefer bins near/below mean residual (fuller bins)
    score += 3.0 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: penalize slightly so we prefer reusing bins unless fit is poor
    if bin_residual == bin_capacity {
