}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always ideal
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the post residual: residues that are hard to fill later
    // (small, odd-ish leftovers) are penalized; "usable" classes are rewarded.
    let r = post_residual % 10;
    let class_penalty = match r {
        0 => -6.0,                 // clean decade residual, easy to reuse
        1 | 2 | 3 => 8.0,          // sliver dead space
        4 | 5 | 6 => -2.0,         // mid-range, moderately reusable
        _ => 3.0,                  // 7..9 awkward
    };
    score += class_penalty;

    // Quantized fill-level of the bin (integer division on capacity fractions)
    let quarter = bin_capacity / 4;
    let fill_level = (bin_residual / quarter) as f64; // 0..=4
    // Prefer filling already-committed bins: deeper bins get priority
    score -= fill_level * 4.0;

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_waste = post_residual - next_item_size;
        if lookahead_waste == 0 {
            score -= 40.0; // chain a perfect fit
        } else {
            score -= 10.0 * (1.0 - (lookahead_waste as f64) / (post_residual as f64));
        }
    } else if next_item_size > post_residual {
        // next item can't use this leftover: penalize proportionally to dead space
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Modulo threshold on post_residual vs next_item_size harmonic classes
    if next_item_size > 0 && (post_residual % next_item_size.max(1)) == 0 && next_item_size <= post_residual {
        score -= 12.0; // post residual is an exact multiple of next item
    }

    // New-bin candidate handling: only attractive early or when open bins are full-ish
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_pressure = mean_residual / bin_capacity as f64;
        // penalize opening new bins when existing bins have room
        score += 30.0 + 40.0 * (1.0 - progress) - 20.0 * avg_pressure;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Mild preference to balance bin count: more open bins -> prefer reusing bins
    score += 0.5 * open_bins_count as f64;

    // Small noise-free tie-break: prefer tighter fit overall
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

