        let gap_norm = gap / cap;
        // Prefer post_residual slightly above next item size; penalize both too small and too large.
        score -= 30.0 * (1.0 - 4.0 * gap_norm * gap_norm) * (0.3 + 0.7 * progress);
    } else {
        // Last item: strongly favor filling bins as completely as possible.
        score -= 50.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Mild penalty for proliferation of open bins early on (smooth in open_bins_count).
    score += (open_bins_count as f64).powi(2) * 0.05 * (1.0 - progress);

    // Mean-residual coupling: if this bin's residual deviates far below the mean,
    // it is an outlier bin; smooth quadratic penalty/reward.
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (1.0 - 2.0 * progress);

    // New-bin candidate: penalize opening a fresh bin unless residuals are generally tight.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - mean_residual / cap;
        score += 20.0 + 60.0 * (1.0 - tightness) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "reusable" class (divisible by common item sizes) are favored.
    let pr = post_residual;
    let pr_class = pr % 10; // capacity fractions on a 10-grid
    let class_bonus: f64 = match pr {
        0 => -60.0,                       // perfect fit: best outcome
        _ if pr % 50 == 0 => -35.0,       // leaves a half-bin class
        _ if pr % 25 == 0 => -25.0,       // quarter-bin class
        _ if pr % 20 == 0 => -20.0,       // fifth-bin class
        _ if pr % 10 == 0 => -12.0,       // decile class: broadly reusable
        _ if pr < 10 => 40.0,             // dead space: unusable sliver
        _ => 0.0,
    };
    score += class_bonus;

    // Integer-division threshold coupling: post_residual bucket vs next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead fits exactly into the leftover: strong reward,
            // amplified when the fit is tight (small post-post residual).
            let post_post = pr - next_item_size;
            let tight = (post_post as f64 / bin_capacity as f64) * 80.0;
            score -= 30.0 - tight; // tight fit => subtract up to ~30
            if post_post % 10 == 0 {
                score -= 8.0; // chained harmonic class
            }
        } else {
            // Lookahead cannot use this bin's leftover: penalize dead space
            // proportionally to how small the leftover is.
            let dead = (pr as f64) * (next_item_size as f64 / bin_capacity as f64);
            score += dead * 0.5;
        }
    } else {
        // Last item: drive residuals to zero as hard as possible.
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the residual would be near-dead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr >= 10 {
            score -= 25.0;
        } else {
            score += 15.0; // only bin left but creates dead space
        }
    }

    // New-bin candidate handling: an empty bin is only attractive early in
    // the stream or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = (open_bins_count as f64) / (1.0 + mean_residual / bin_capacity as f64);
        score += 55.0 + progress * 30.0 - openness * 5.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big next item: fresh capacity has value
        }
    }

    // Mild preference for tighter existing bins as the stream matures.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * (10.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64));

    // Penalize leftovers that sit in awkward modulo classes (3, 7 mod 10).
    if pr > 0 && (pr_class == 3 || pr_class == 7) {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let mut score = pr;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward residuals that can host the next item;
    // penalize residuals that strand dead space relative to the lookahead.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
        } else {
            score += 0.6 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score = -1000.0;
        } else {
            score += 30.0 * (1.0 - isz / cap);
            if fitting_bins_count == 0 {
                score -= 200.0;
            }
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 4.0 * progress;
            // Small items fit anywhere; keep them out of fresh bins.
            if fitting_bins_count > 0 && isz < 0.5 * cap {
                score += 25.0;
            }
            // If the only fitting bin has a terrible fit, prefer opening fresh.
            if fitting_bins_count == 1 && pr > 40.0 {
                score -= 15.0;
            }
            // Fragmentation check: fresh residual more useful than mean residual.
            if pr > mean_residual * (0.5 + progress) && fitting_bins_count > 1 {
                score -= 10.0;
            }
        }
    }

    // Tightness: reward bins where the item fills a large fraction of the residual.
    let tightness = isz / bin_residual.max(1) as f64;
    score -= 3.0 * tightness;

    // Tiny stranded residuals are nearly worthless; slight reward for creating them.
    if post_residual > 0 && post_residual < 20 {
        score -= 15.0;
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized.
    let dead = if post_residual == 0 {
        -50.0 // perfect fit: strong reward
    } else if post_residual < 10 {
        60.0 // unusable sliver
    } else if post_residual < 20 {
        30.0 // nearly dead space
    } else if post_residual < 30 {
        10.0
    } else {
        0.0
    };
    score += dead;

    // Reward tight fits proportionally (small post_residual relative to residual).
    if bin_residual > 0 {
        score -= (item_size as f64 / bin_residual as f64) * 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it only
    // wins when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 1.5;
    } else {
        // Last-chance bonus: if this is the only fitting bin, prefer using it
        // over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Open-bin pressure: many open bins -> favor consolidation into
        // already-open bins rather than spreading.
        score -= (open_bins_count as f64).ln() * 4.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward it;
    // otherwise penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Late in the stream, slightly prefer filling existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Mild attraction toward bins with residuals near the mean (typical bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
