    // favor bins near or above the mean residual.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge or no good fits exist.
    if bin_residual == bin_capacity {
        let base = 35.0;
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += base + (1.0 - item_frac) * 40.0;
        // late in stream, be more conservative about opening bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for consolidating among fewer bins early on.
    score += open_bins_count as f64 * 0.05;

    score
}

