pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest plausible item is nearly unusable.
    let t = step_index as f64 / (total_items.max(1) as f64);

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
