    // otherwise penalize wasting space the next item needed.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if (bin_residual as u32) >= next_item_size && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Global state coupling: when many bins are open with large mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let consolidation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 10.0 * consolidation * (open_bins_count as f64).ln().max(0.0);

