    // over time (late in the stream, prefer closing out open bins).
    if bin_residual == bin_capacity {
        let handicap = 15.0 * (1.0 - 0.5 * t);
        score += handicap;
        // Opening a new bin is more attractive if no existing bin fits well.
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Mild time-horizon shaping: early on, be slightly more exploratory
    // (favor balanced residuals); late, pack aggressively.
    score += 5.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    score
}

