    let x = post / cap;

    // Non-linear polynomial in post_residual, modulated by stream progress
    let mut score = post * (1.0 + 0.8 * progress);
    score -= 0.35 * (post * post) / cap * (1.0 + progress);
    score += 0.15 * (post * post * post) / (cap * cap) * (1.0 - progress);

    // Tightness of fit: reward small post-residual non-linearly
