pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 residue classes.
    // Residuals that are "usable" for typical small items (multiples of 10)
    // get a bonus (subtract); awkward residues get penalized.
    let pr = post_residual;
    let residue = pr % 10;
    score -= 8.0 * (1.0 - residue as f64 / 4.5).abs().min(1.0); // residue 0 best, ~4-5 worst

    // Dead-space penalty: residuals below the smallest plausible item are wasted.
    if pr < 10 && pr > 0 {
        score += 25.0;
    } else if pr == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Harmonic pairing: does post_residual combine with the next item
    // to a multiple-of-10 class (e.g. pr == next, pr + next == 10k)?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // exact pair fit next round
        } else if (pr + next_item_size) % 10 == 0 && pr >= next_item_size {
            score -= 10.0; // harmonic complement
        } else if next_item_size > pr {
            score += 5.0; // next item cannot use this bin's remainder anyway
        }
    }

    // Capacity-fraction thresholds: residual as fraction of capacity.
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score -= 6.0; // bin still half full: keep it attractive
    } else if frac < 0.1 && pr > 0 {
        score += 10.0 * (0.1 - frac); // penalize slivers
    }

    // Integer-division thresholds on post_residual: which harmonic slot it lands in.
    let slot = pr / 25; // 0,1,2,3 -> quarter classes
    score -= 3.0 * slot as f64; // prefer bins with larger quarter-class

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: only open a new bin early in the stream
    // when the current bin's residual is very tight, otherwise discourage.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < 15.0 && open_bins_count > 0;
        if tight && progress < 0.9 {
            score -= 18.0; // all open bins nearly full -> fresh bin is good
        } else {
            score += 30.0; // keep filling open bins
        }
    }

    // Mild tie-break toward bins tighter than the mean.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

