    // Harmonic residue-class shaping (kept from parent, softened).
    let residue = pr as u32 % 10;
    score -= 4.0 * (1.0 - residue as f64 / 4.5).abs().min(1.0);

    // Dead-space penalty for unusable slivers.
    if post_residual > 0 && post_residual < 20 {
        score -= 15.0;
