    // Lookahead: exact pair fit with next item is nearly as good as a perfect fit.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            // Remaining space after next item: prefer compact leftovers.
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
        } else {
            // Next item cannot use this bin's remainder.
            score += 0.6 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
        }
        // Harmonic complement (multiple-of-10 pairing) bonus.
        if (post_residual + next_item_size) % 10 == 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Capacity-fraction thresholds.
    let frac = pr / cap;
    if frac > 0.5 {
        score -= 6.0;
    } else if frac < 0.1 && post_residual > 0 {
        score += 10.0 * (0.1 - frac);
    }

    // Quarter-class slot preference.
    let slot = post_residual / 25;
    score -= 3.0 * slot as f64;

    // Tightness coupling: prefer bins where the item fills a large fraction.
    let tightness = isz / bin_residual.max(1) as f64;
    score -= 3.0 * tightness;

    // Last-chance bin: avoid opening new bins needlessly.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: open fresh bin only when all open bins are tight,
    // or when the item is small enough that a fresh bin wastes little.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - isz / cap);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        score -= 4.0 * progress;
        if fitting_bins_count > 0 && isz < 0.5 * cap {
            score += 25.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 && progress < 0.9 {
