pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Crowding pressure: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual deviates favorably from the mean (below-mean residual = fuller bin).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // reserving fresh space for a large upcoming item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - 3.0 * x + 2.0 * x * x);
    let coupling = pr * (1.0 + progress * (poly * 4.0 - 1.0));

    let mut score = coupling;

    // Reward tight fits more strongly as stream progresses
    score -= (item_size as f64 / cap) * (0.5 + progress);

    // Penalize near-emptying fits that waste large residual on small items
    if post_residual > 0 {
        let waste = (post_residual as f64 / cap).powi(3);
        score += waste * (10.0 + 20.0 * progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * progress;
    }

    // Lookahead: favor bins that can also fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // New-bin candidate handling: prefer new bin only when residuals are large
    if bin_residual == bin_capacity {
        score += 2.0 * mean_residual / cap - 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 (capacity 100 -> decile classes)
    let class = post_residual % 10;
    // Residues divisible by 10 (class 0) are "harmonic": they can host round-sized
    // items cleanly; odd/prime-ish residues create dead-space risk.
    let harmonic = match class {
        0 => 1.0,
        5 => 0.5,
        _ => 0.0,
    };
    score -= 6.0 * harmonic;

    // Integer-division threshold on post_residual: small residuals (< 10) are dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit is ideal
    }

    // Lookahead coupling: does next_item_size divide into post_residual harmonically?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let quotient = post_residual / next_item_size;
            let remainder = post_residual % next_item_size;
            // Exact division (remainder 0) means the next item tiles this bin perfectly.
            if remainder == 0 {
                score -= 12.0;
            } else {
                score += (remainder as f64) * 0.4;
                // Bonus if multiple copies still fit (quotient >= 2)
                if quotient >= 2 {
                    score -= 4.0;
                }
            }
        } else {
            // Next item cannot fit here; residual becomes a waiting buffer.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins already fit, scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 18.0 + 12.0 * (1.0 - progress) + (open_bins_count as f64) * 0.5;
    }

    // Coupling with mean residual: prefer bins whose residual is below mean
    // (concentrate filling), reward tightness relative to the fleet average.
    let diff = mean_residual - post_residual as f64;
    score -= 0.3 * diff;

    // Slight preference for bins with larger pre-residual usage (bin_residual small)
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 9.0; // smallest item is ~10, so residual < 10 is dead space
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 12.0;
    }

    // Reward very tight fits (post_residual near zero but still usable).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 && bin_residual == item_size {
        score -= 40.0;
