    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // (i.e., current fit would create dead space or this is a poor placement).
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 5.0;
        // But if placing here would leave dead space, opening a fresh bin
        // becomes competitive.
        if (post_residual as f64) < dead_zone {
            score -= 20.0;
        }
        // Prefer new bin when the alternative wastes a lot relative to mean.
        if (post_residual as f64) > mean_residual + 10.0 {
            score -= 8.0;
        }
        // Early in the stream, opening bins is cheap; later, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead coupling: if the next item could use this bin's post_residual,
    // reward leaving a useful gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize leaving a gap just under the next item's size (near-miss waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
