    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10);
        if poor_fit {
            score -= 70.0 + 20.0 * progress;
        } else {
            score += 80.0; // discourage wasting an open bin
        }
    }

    // Slight preference for keeping fewer open bins when residuals are large
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

