    score += amp * cap * pr_norm * pr_norm;

    // Reward filling bins tightly: smooth cubic bonus for near-full placements.
    let fill = 1.0 - pr_norm;
    score -= 30.0 * fill * fill * fill * (0.5 + 0.5 * progress);

    // Penalize bins whose post-residual can't fit the lookahead item (waste),
    // smoothly scaled by how far off it is.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr < n {
            let gap = (n - pr) / cap;
            score += 20.0 * gap * (1.0 + progress);
        } else {
            // mild reward if lookahead fits snugly
            let snug = 1.0 - ((pr - n) / cap);
            score -= 8.0 * snug * snug * snug;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm) + 5.0;
    }

    // Many open bins: prefer consolidating into existing ones (mild).
    score += 0.02 * open_bins_count as f64 * pr_norm;

    // Prefer bins below mean residual (keeps residual distribution balanced).
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: must not win unless placement into open bins is bad.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 10 are
    // more likely to host future items (typical size granularity).
    let r = post_residual as i64;
    let r_mod = (r % 10) as f64;
    let residue_penalty = if r == 0 { -30.0 } else {
        let d = r_mod.min(10.0 - r_mod); // distance to nearest multiple of 10
        d * 2.5
    };
    score += residue_penalty;

    // Penalize dead space that is too small for the smallest plausible item (1..100 range):
    // residuals below 20 are nearly unusable "harmonic dead zones".
    if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Perfect harmonic fit: post_residual equals next item size
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // This bin cannot host the next item; slight penalty unless it's a fresh bin.
            score += 6.0;
        }
    }

    // Integer-division thresholds on post_residual (capacity fractions).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += if frac < 0.1 { 15.0 }        // tiny unusable sliver
             else if frac < 0.25 { 5.0 }   // poor
             else if frac < 0.5 { 0.0 }    // decent
             else if frac < 0.75 { -5.0 }  // good
             else { -10.0 };               // roomy

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Fresh-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (many fitting bins -> discourage new bin).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else if fitting_bins_count == 1 {
            score += 30.0; // defer to the last-chance open bin
        } else {
            score += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins tighter than the mean (better packing density).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Modulo-3 class of item size: items near multiples of 3 partition capacity
    // more evenly; small bonus for bins whose residual shares the item's class.
    let cls = (item_size % 3) as f64;
    let bcls = (bin_residual % 3) as f64;
    if cls == bcls {
        score -= 2.0;
    }

    score
}

