pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone_max = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_zone_max {
        score += (dead_zone_max - post_residual as f64) * 6.0; // worst at gap=1
    }
    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual && post_residual - next_item_size <= 2 {
            score -= 10.0;
        }
        // Penalize leaving a gap just below the next item size (near-miss dead space).
        if next_item_size > post_residual && next_item_size - post_residual <= 8 {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are congested or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (open_bins_count as f64) * 1.5;
        // Base penalty so new bins are opened only when justified.
        score += 55.0 + congestion - progress * 10.0;
        // Large items justify a fresh bin more readily.
        if item_size >= 50 {
            score -= 12.0;
        }
        // If the next item is large and this item is small, a fresh bin preserves flexibility.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 18.0;
        }
    } else {
        // Open-bin pressure: prefer filling bins that are already committed,
        // slightly favoring emptier bins to consolidate load.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 8.0;
        score += (open_bins_count as f64) * 0.4;
        // Prefer bins whose residual deviates favorably from the mean residual
        // (place into bins with below-average residual to balance dead space).
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward residuals that can host the next item; penalize stranded space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0; // next item fills this bin exactly: near-perfect pairing
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
        } else {
            score += 0.6 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score = -100.0;
        } else {
            score += 30.0 * (1.0 - isz / cap);
            if fitting_bins_count == 0 {
                score -= 200.0;
            }
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= 4.0 * progress;
            // Small items are cheap to place in a fresh bin and keep big bins
            // available for big items.
            if fitting_bins_count > 0 && isz < 0.5 * cap {
                score += 25.0;
            }
            // Existing bins are fragmented: fresh residual more useful than mean.
            if pr > mean_residual * (0.5 + progress) {
                score -= 20.0;
            }
        }
    }

    // Tightness pressure: prefer filling bins as fully as possible.
    let tightness = isz / bin_residual.max(1) as f64;
    score -= 3.0 * tightness;

    // Small leftover residual is valuable: it is nearly a perfect fit slot.
    if post_residual > 0 && post_residual < 20 {
        score -= 15.0;
    }

    // Mild consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual small).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack.min(20.0) * 0.5; // best when next item fits snugly
        } else {
            // Penalize dead space the next item cannot use.
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.6;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins that are already
    // below-average residual (consolidating fuller bins).
    let resid = post_residual as f64;
    if mean_residual > 0.0 {
        score += (resid - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh empty bin when the
    // item is large relative to residual capacity (poor fit anywhere).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 80.0; // an open bin could chain the next item: avoid new bin
        } else if tightness > 0.7 || fitting_bins_count == 0 {
            score -= 20.0; // large item / no alternatives: new bin is fine
        } else {
            score += 15.0; // default: prefer filling existing bins
        }
    }

    // Late in the stream, be more conservative: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - resid / bin_capacity as f64);

    // Mild preference for balancing bin count.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space, normalized by capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac * bin_capacity as f64;

    // Lookahead: if the next item exactly or nearly fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use is worse late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0 + 6.0 * (item_size as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are large relative to the item (poor fits everywhere) or early stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread = mean_residual - post_residual as f64; // new bin has residual = capacity
        let pressure = open_bins_count as f64;
        // Base cost of a fresh bin, discounted when many open bins are fragmented.
        score += 30.0 - 4.0 * progress - 0.5 * pressure;
        // If mean residual of open bins is small, fresh bin is reasonable.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 12.0;
        }
        // Penalize opening a bin that leaves a large gap unusable by the next item.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 6.0;
        }
        let _ = spread;
    }

    // Mild preference for bins whose residual is already below the mean (consolidating fragmentation).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: normalized post-residual dead space
    let mut score = pr / cap;

    // Smooth non-linear penalty for small-but-nonzero residual (dead space)
    let r_norm = pr / cap;
    score += 0.6 * (1.0 - r_norm) * (1.0 - r_norm) * (1.0 - r_norm) * (1.0 - r_norm);

    // Polynomial coupling with stream progress: prefer tight fits later in stream
    score -= (1.0 - r_norm) * (0.3 + 0.5 * progress * progress);

    // Reward post-residual that can still host the next item (smooth interaction)
    if nx > 0.0 {
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        let smooth = fit_next * (1.0 - ((pr - nx) / cap).abs());
        score -= 0.8 * smooth * (0.5 + 0.5 * progress);
        // Penalize post-residual that is too small for next item (wasted space)
        score += 0.4 * (1.0 - fit_next) * (nx / cap) * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else {
        score += 0.1 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild penalty for opening new bins when many bins already open and mean residual is high
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 0.5 + 0.3 * (open_bins_count as f64).ln().max(0.0) - 0.4 * (mean_residual / cap);
        // allow new bin if current item is huge relative to mean residual
        score -= 0.6 * (it / cap) * (1.0 - mean_residual / cap);
    }

    // Small penalty coupling item size with progress (pack big items early)
    score += 0.2 * (it / cap) * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
