    }

    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap) ;
        if fitting_bins_count == 0 { score -= 200.0 ; }
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        score -= 4.0 * progress ;
        if fitting_bins_count > 0 && isz < 0.5 * cap { score += 25.0 ; }
        // opening a new bin is less attractive when existing bins have plenty of room
        if mean_residual > 0.35 * cap && fitting_bins_count > 0 { score += 18.0 ; }
