    let tightness = isz / bin_residual . max (1) as f64 ;
    score -= 3.0 * tightness ;

    if post_residual > 0 && post_residual < 20 { score -= 15.0 ; }
    // avoid leaving awkward mid-size gaps that few items can use
    if post_residual >= 20 && post_residual < 40 { score += 6.0 ; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
