}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual exactly divisible by common small item sizes
    // (residual reusable by typical items 10..80).
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if post_residual <= 10 {
        score += 60.0; // dead space below minimum item size
    } else {
        let mut divisible_bonus = 0.0;
        for d in [10u32, 20, 25, 40, 50, 80] {
            if post_residual % d == 0 {
                divisible_bonus += 25.0;
            }
        }
        score -= divisible_bonus;
        // Fractional capacity class: prefer residuals in "half-bin" harmonic band
        let frac = pr / cap;
        if (0.45..=0.55).contains(&frac) {
            score -= 15.0;
        } else if frac < 0.2 {
            score += 30.0 * (0.2 - frac) / 0.2;
        }
    }

    // Lookahead coupling: does post_residual accommodate the next item exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 40.0 * (gap as f64 / cap).min(1.0);
            // harmonic pair check: residual splits into two next-item chunks
            if post_residual % next_item_size.max(1) == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot fit here; residual value drops
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it attractive only when the item is huge relative
    // to typical residuals and few bins fit it.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / cap) * (fitting_bins_count as f64).max(1.0);
        score -= 30.0 * pressure;
        // penalize opening new bins mid-stream when mean residual is healthy
        score += (mean_residual / cap) * 50.0;
    }

    // Stream progression: early on, prefer tighter packing (minimize post_residual);
    // late, prefer closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (pr / cap);

    // Spread penalty: avoid fragmenting when many bins are open.
    score += 0.1 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (min item size 1, but useful threshold ~12) are dead space.
    // Penalize gaps in the "unusable" band [0, 12) heavily; reward residuals
    // that can still host a meaningful item.
    if post > 0.0 && post < 12.0 {
        score += (12.0 - post) * 6.0; // dead-space penalty up to ~72
    } else if post >= 12.0 {
        score -= 8.0; // bin stays usable
    }

    // Perfect fits are ideal.
    if post == 0.0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained placement).
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // encouraging consolidation when many bins are already open.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins attractive only when current bins
    // would leave large post residuals relative to capacity (poor fits elsewhere).
    if bin_residual == bin_capacity {
        // Baseline competitiveness: a fresh bin scores like a perfect-fit
        // residual (0) plus a mild opening cost that grows with stream progress.
        score = 5.0 + (step_index as f64 / total_items.max(1) as f64) * 4.0
            + (open_bins_count as f64) * 0.8;
        if next_item_size > 0 && next_item_size as f64 <= cap {
            score -= 2.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose post residual keeps
    // the fleet near the mean (balanced residual profile).
    score += (post - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match of post_residual to next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // exact 2-step fit: place here
        } else if (post_residual as i64 - next_item_size as i64) > 0 {
            // next item fits after this placement: mild reward proportional to closeness
            score -= (30.0 - diff as f64).max(0.0);
        } else {
            // next item would NOT fit: penalize creating a tight dead end
            score += (diff as f64) * 0.6;
        }
        // small lookahead shaping: small post_residual generally bad unless it matches next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    } else {
        // last item: just minimize waste
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Compare residual against mean: below-mean residual (tight bin) is good to fill.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Discourage opening new bins when open bins are plentiful and roomy.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless it's early or open bins are tight
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress);
        if mean_residual < item_size as f64 * 0.5 {
            score -= 30.0; // open bins too tight -> new bin OK
        }
    }

    // Prefer filling bins with small residual relative to capacity.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let isz = item_size as f64 ;

    if post_residual == 0 { score -= 900.0 ; }

    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if next_item_size == post_residual {
            score -= 700.0 ;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx ;
            score -= 250.0 * (1.0 - fill_after_next / cap) ;
            score += 0.4 * fill_after_next ;
            // bonus if the item after next also fits the leftover
            if fill_after_next >= nx as f64 * 0.5 && fill_after_next > 0.0 {
                score -= 40.0 * (fill_after_next / cap) ;
            }
        } else {
            score += 0.6 * pr + 50.0 ;
            if next_item_size <= bin_residual { score += 8.0 ; }
            // penalize bins whose residual is too small to matter for the future
            if (pr as u32) < next_item_size && pr < 0.15 * cap {
                score += 60.0 ;
            }
        }
    }

    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap) ;
        if fitting_bins_count == 0 { score -= 200.0 ; }
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        score -= 4.0 * progress ;
        if fitting_bins_count > 0 && isz < 0.5 * cap { score += 25.0 ; }
        // avoid opening a new bin when many bins can still fit the item
        if fitting_bins_count > 2 { score += 120.0 ; }
    }

    let tightness = isz / bin_residual . max (1) as f64 ;
    score -= 3.0 * tightness ;

    // prefer leaving residuals that match the mean residual scale (less dead space)
    if pr > 0.0 && mean_residual > 0.0 {
        let ratio = pr / mean_residual ;
        if ratio > 0.5 && ratio < 2.0 { score -= 10.0 ; }
        else if pr > mean_residual * 3.0 { score += 12.0 * (ratio - 3.0).min (5.0) ; }
    }

    if post_residual > 0 && post_residual < 20 { score -= 15.0 ; }

    // mild preference for bins with few competitors (better consolidation)
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 6.0 ; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already the base), amplify it.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never fit a typical item again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: when many bins are open, prefer consolidation (favor fuller bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Pull toward the mean residual: prefer bins close to average fullness state.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            -100.0 // nothing fits anywhere: opening new bin is mandatory
        } else {
            // penalize opening a new bin unless item is large relative to capacity
            let big_item = item_size as f64 / bin_capacity as f64;
            20.0 - 25.0 * big_item
        };
        score += desperation;
        // late in the stream, slightly discourage spawning extra bins
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: quadratic penalty on post_residual scaled by stream progress
    score += 2.0 * norm_pr * norm_pr * (0.5 + progress);

    // Interaction between post_residual and mean residual (dead-space coupling)
    score -= 0.5 * norm_pr * (mean_residual / cap) * (1.0 - progress);

    // Lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fit_term = if ni <= pr { 1.0 - (pr - ni) / cap } else { 0.0 };
        score -= 1.5 * fit_term * (1.0 - progress);
    }

    // Last-chance bin bonus: smooth cubic in fitting_bins_count
    let fbc = fitting_bins_count as f64;
    score -= (1.0 / (fbc * fbc + 1.0)) * 3.0 * (0.3 + progress);

    // Mild penalty for opening many bins late
    score += 0.01 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (10/20/25/50) are more reusable -> reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residual classes that align with typical item granularity.
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        if r % 10 == 0 { b += 6.0; }
        if r % 20 == 0 { b += 4.0; }
        if r % 25 == 0 { b += 3.0; }
        if r % 50 == 0 { b += 5.0; }
        b
    };
    score -= harmonic_bonus(post_residual);

    // Penalize "dead zone" residuals: too small to fit the smallest item (1..100
    // unknown, so use half of current item as proxy) but not near zero.
    let dead_threshold = (item_size / 2).max(1);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0;
    }
    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let chain_left = post_residual - next_item_size;
            score -= 12.0;
            score -= harmonic_bonus(chain_left);
            // penalize leaving awkward leftover after the chain
            if chain_left > 0 && chain_left < 5 {
                score += 8.0;
            }
        } else {
            // next item cannot follow here; mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap) * 10.0;
        }
    }

    // Fraction of capacity wasted relative to bin: quadratic penalty on waste.
    let waste_frac = pr / cap;
    score += waste_frac * waste_frac * 15.0;

    // Last-chance bin: if this is the only fitting bin, prefer using it to
    // avoid opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has high raw residual; make it
    // attractive when current fit is poor or open bins are numerous/crowded.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / cap);
        // default new-bin score: baseline mid value minus crowding pressure
        score = cap as f64 * 0.55 - crowded * 2.0;
        // If lookahead is large and residual would be large, new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Early in stream, opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 8.0;
        // But never open a new bin when a near-perfect fit exists: raise floor.
        if post_residual == 0 { score += 100.0; }
    }

    // Modulo-threshold tiebreak on integer division of post_residual by 10:
    // prefer residuals in coarse buckets that are larger (more usable).
    let bucket = post_residual / 10;
    score -= bucket as f64 * 0.5;

    // Mean residual context: if this bin's residual is far below mean, it's
    // already fragmented; penalize adding more fragmentation.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let isz = item_size as f64 ;
    if post_residual == 0 { score -= 900.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if next_item_size == post_residual {
            score -= 750.0 ;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx ;
            score -= 250.0 * (1.0 - fill_after_next / cap) ;
            score += 0.4 * fill_after_next ;
            // reward bins whose leftover stays large enough to absorb a second follow-up item
            if fill_after_next >= nx * 2.0 { score -= 40.0 ; }
        } else {
            score += 0.6 * pr + 50.0 ;
            if next_item_size <= bin_residual { score += 8.0 ; }
            // penalize creating a residual that is unusable for the next item
            if pr > 0.0 && pr < nx as f64 * 0.5 { score += 30.0 ; }
        }
    }
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap) ;
        if fitting_bins_count == 0 { score -= 200.0 ; }
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        score -= 4.0 * progress ;
        if fitting_bins_count > 0 && isz < 0.5 * cap { score += 25.0 ; }
        // discourage opening a new bin when many open bins fit the item well
        if fitting_bins_count >= 2 && isz <= 0.35 * cap { score += 60.0 ; }
    }
    let tightness = isz / bin_residual . max (1) as f64 ;
    score -= 3.0 * tightness ;
    if post_residual > 0 && post_residual < 20 { score -= 15.0 ; }
    // small residuals slightly above the tiny threshold are still nearly dead space
    if post_residual > 20 && post_residual < 35 && (next_item_size as f64) > pr {
        score -= 5.0 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 10 {
        // Unusable tiny gap: heavy penalty scaled by how close it is to a "just missed" fit.
        score += 60.0;
    }

    // Penalize residual that cannot fit the lookahead item (poor two-step packing).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residual that exactly or nearly accommodates the next item.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / 20.0).max(0.0);
        }
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage spreading across many bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current bin would be left
    // with a large usable residual or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0;
        if !poor_fit_elsewhere && post_residual < 40 {
            score += 35.0;
        }
        // Mild steady pressure against needless new bins.
        score += 5.0;
    }

    // Mean-residual coupling: if the fleet is already loose, prefer bins keeping it compact.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact match strongly, decay smoothly for near matches.
        let match_reward = 60.0 * (-diff / 12.0).exp();
        score -= match_reward;

        // If the next item can't fit in the post-residual, penalize proportional to the shortfall.
        if (post_residual as i64) < next_item_size as i64 {
            let shortfall = (next_item_size as i64 - post_residual as i64) as f64;
            score += 0.5 * shortfall;
        }
    } else {
        // Last item: just minimize residual waste (score already does).
        score += 0.0;
    }

    // Penalize creating small unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer tighter bins (already via post_residual).
        score += 0.0;
    }

    // Contextual coupling with mean residual: bins tighter than average are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Prefer reusing bins over opening new ones, more so early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early on.
        score += 20.0 + 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Slight reward for bins that will be nearly full.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
