    }

    // avoid leaving large dead space: prefer bins where residual after placement
    // stays close to a reusable small size relative to mean residual
    if pr > 0.0 {
        let dead_ratio = pr / cap ;
        if dead_ratio > 0.55 && fitting_bins_count > 1 {
            score += 20.0 * (dead_ratio - 0.55) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size is wasted. Penalize residuals that are unusable.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize post-residuals that are too small to ever be useful
    // (assuming minimum item size 1, but tiny slivers are still unlikely
    // to be filled under unknown distributions).
    if post_residual > 0 && post_residual < 12 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer bins that would leave a residual
        // matching the lookahead item size.
        if next_item_size > 0 && post_residual >= next_item_size {
            let match_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 25.0 * match_quality;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0; // lookahead won't fit here afterwards
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Time horizon: early in the stream, be conservative and keep bins
    // flexible (favor larger post_residuals); late in the stream, pack
    // aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0 * (fitting_bins_count as f64).min(5.0);

    // Global state: when many bins are open, discourage opening new ones;
    // the empty-bin candidate (bin_residual == bin_capacity) gets a penalty
    // that grows with the number of open bins and mean residual availability.
    if bin_residual == bin_capacity {
        let mean_res = mean_residual;
        score += 30.0 + 6.0 * open_bins_count as f64 + 0.4 * mean_res;
        // But late in the stream with a poor fit elsewhere, new bin is fine.
        if progress > 0.8 && post_residual >= 0 {
            score -= 25.0 * progress;
        }
        // If next item is large and this fresh bin could hold both, reward.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Prefer placing into bins whose residual deviates favorably from the mean:
    // a bin with much less residual than average is "almost full" — finish it off.
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score -= 0.15 * (-dev);
    } else {
        score += 0.05 * dev;
    }

    // Mild penalty for item dominating the bin (wasteful on small bins).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score += 10.0 * fill_ratio * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
