    // Best-fit tightness preference
    let tightness = isz / bin_residual.max(1) as f64;
    score -= 3.0 * tightness;

    // Tiny leftover residual is valuable — near-closed bins
    if post_residual > 0 && post_residual < 20 {
        score -= 15.0;
