            // Next item fits but leaves its own residual: harmonic class of chained residual.
            let chained = pr - next_item_size;
            let chain_class = chained % 10;
            if chain_class == 0 {
                score -= 10.0;
            } else if chain_class <= 2 {
                score -= 6.0;
            } else {
                score += 2.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty for stranding space.
            score += (next_item_size - pr).min(20) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && pr <= 20 {
        score -= 15.0;
    } else if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the current fit is poor or no good class exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If the item is large relative to capacity, a fresh bin is safer.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins with low mean residual: opening new bins is wasteful.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
    }

