        if post_residual as u32 == next_item_size {
            score -= 60.0; // perfect 2-item chain fill
        } else if post_residual as u32 >= next_item_size {
            // reward tightness of the lookahead fit
            let slack = (post_residual as u32 - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
