    // for big items; bins looser than the mean should absorb small leftovers.
    let residual_f = bin_residual as f64;
    let mean_gap = residual_f - mean_residual;
    let item_frac = item_size as f64 / bin_capacity as f64;
    if item_frac > 0.5 {
        // large item: prefer bins with residual close to item (tight fit)
        score += 0.3 * mean_gap;
    } else {
        // small item: prefer looser-than-mean bins to consolidate tight ones
        score -= 0.15 * mean_gap;
    }

