    // would strand this residual entirely, so strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size),
    // unless the lookahead chain consumed them.
    if post_residual > 0 && post_residual < 10 && next_item_size as u32 != post_residual {
        score += 15.0;
