    if open_bins_count > 0 {
        let mean_usage = bin_capacity as f64 - mean_residual;
        let this_usage = (bin_capacity - bin_residual) as f64;
        if this_usage < mean_usage {
            score += 0.08 * (mean_usage - this_usage);
        } else {
            score -= 0.04 * (this_usage - mean_usage);
        }
