        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
        // Avoid wasting new bins on small items when a loose bin exists
        if fitting_bins_count > 0 && isz < 0.5 * cap {
            score += 25.0;
        }
    }

    // Tightness preference (best-fit flavor)
    let tightness = isz / bin_residual.max(1) as f64;
    score -= 3.0 * tightness;

    // Reward near-closure residuals
    if post_residual > 0 && post_residual < 20 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = it / cap; // item fill fraction
    let pr_norm = pr / cap;

    // Base: penalize leftover space, quadratically (dead space is super-linearly bad)
    let mut score = pr_norm * pr_norm * cap;

    // Smooth coupling: late in the stream, tight fits matter more
    let tightness = 1.0 - pr_norm; // how full the bin becomes
    let progress_coupling = progress * tightness * tightness;
    score -= 12.0 * progress_coupling * cap * fill;

    // Reward near-perfect fits with smooth bell-shaped term
    let perfect = (pr_norm * cap - 0.0).exp() * (-pr_norm * pr_norm * 8.0).exp();
    score -= 10.0 * perfect * (0.3 + 0.7 * progress);

    // Lookahead: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr - nx).max(0.0) / cap;
        let match_quality = 1.0 - ((pr - nx) / cap).abs();
        score -= 6.0 * usable * (0.5 + 0.5 * match_quality);
        // Penalize residuals that almost-but-not-quite fit the next item
        let gap = pr - nx;
        if gap > 0.0 && gap < 10.0 {
            score += 4.0 * (1.0 - gap / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.4 + 0.6 * progress);
    }

    // Mild penalty for spreading across many open bins vs. consolidating
    let mean_gap = (mean_residual - pr).abs() / cap;
    score += 2.0 * mean_gap * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make empty bins less attractive unless item is large or fits are scarce
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        let big_item = fill * fill;
        score += 8.0 * (1.0 - big_item) * (1.0 - scarcity) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let isz = item_size as f64;
    let pr = post_residual as f64;

    // Perfect fill: bin becomes exactly full -> huge reward
    if post_residual == 0 {
        score -= 900.0;
    }

    // Two-step lookahead: reward bins whose post_residual closely matches next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0; // exact chain fit
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
        } else {
            // Dead space: next item cannot follow in this bin; penalize proportionally
            score += 0.6 * pr + 50.0;
            // Extra penalty if next item would have fit with slightly more room
            if next_item_size <= bin_residual {
                score += 8.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter/looser than average appropriately
    score += 0.35 * (pr - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap);
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
        // Discourage wasting a fresh bin on small items when alternatives exist
        if fitting_bins_count > 0 && isz < 0.5 * cap {
            score += 25.0;
        }
    }

    // Slight preference for tighter bins early (best-fit flavor)
    let tightness = isz / bin_residual.max(1) as f64;
    score -= 3.0 * tightness;

    // Tiny leftover fragments are valuable: keep bins that can absorb small stragglers
    if post_residual > 0 && post_residual < 20 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot band" does the leftover fall in?
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: tiny dead space (1..=5) -> mild reward.
    // Class 2: mid leftover usable by typical items -> neutral.
    // Class 3: large leftover -> penalize mildly (wasteful unless bin was huge).
    let harmonic = post_residual % 25;
    match harmonic {
        0 => score -= 40.0,
        1..=5 => score -= 12.0,
        6..=12 => score -= 3.0,
        _ => {}
    }

    // Integer-division thresholds: leftover big enough to host a future item?
    if post_residual >= 60 {
        score -= 8.0; // keeps a "half bin" alive
    } else if post_residual >= 30 {
        score -= 2.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 6.0; // awkward sliver: dead space risk
    }

    // Lookahead coupling: does this post_residual form a harmonic pair with next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // exact chain fit
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 25.0; // near-exact chain
        } else if next_item_size > post_residual && next_item_size > 0 {
            // next item won't fit here; leftover becomes dead unless reusable
            score += (next_item_size as f64) * 0.05;
        }
        // modulo harmony: next item and leftover share a class (both multiples of 10-ish)
        if post_residual % 10 == 0 && next_item_size % 10 == 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits poorly and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) < 5.0 && post_residual > 0;
        if poor_fit || open_bins_count == 0 {
            score -= 45.0;
        } else {
            score += 25.0 + 20.0 * progress;
        }
    }

    // Mean-residual context: if this bin's residual is far below average, it's a laggard; use it.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.15;
    } else {
        score += (-dev) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap is "unusable" if it cannot hold even the smallest plausible item (1..~20).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // total dead space: worst outcome
        } else if post_residual <= 20 {
            score += 25.0; // nearly dead: only tiny items can use it
        } else if post_residual <= 35 {
            score += 8.0; // marginal usefulness
        } else {
            score -= 6.0; // large remaining space is valuable
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 40.0;
    }

    // Dead space relative to the incoming item: wasting a big bin on a small item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - fill_ratio));

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item can use the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 20.0; // next item cannot use the gap -> dead space likely
    }

    // New-bin candidate (empty bin): make it unattractive unless open bins are bad fits.
    if bin_residual == bin_capacity {
        // Baseline: opening a bin costs like having post_residual = capacity - item.
        // Add pressure that grows with open bins count so we consolidate when possible.
        score += 10.0 + 1.5 * open_bins_count as f64;
        // But late in the stream with many bins, avoid cramming: slight relief.
        if progress > 0.8 && fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mean residual context: if this bin's residual is far below average, it is a
    // tight fit; prefer using tight bins (keeps large residuals for large items).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less wasted space relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness;

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item fills bin exactly
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover slack after that
            let slack_after_next = post - nxt;
            score -= 10.0 * (1.0 - slack_after_next / (bin_capacity as f64));
            score += 0.15 * slack_after_next;
        } else {
            // next item cannot use this bin's residual: dead-space risk
            let waste = nxt - post;
            score += 0.10 * waste.min(50.0) as f64;
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates
    // favorably (using larger residuals keeps mean low for future items).
    score += 0.3 * (post_residual as f64 - mean_residual).max(-50.0);

    // Last-chance bin: strongly favor using the only fitting bin
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in the stream, be more willing to open/keep bins flexible;
    // late in the stream, prioritize tight packing aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Discard tiny unusable residuals unless they enable a chain.
    if post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 8.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slight penalty so decent existing bins win
        score += 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity && fitting_bins_count <= 1 {
            score -= 20.0; // open fresh bin when existing options are poor
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let isz = item_size as f64 ;
    let res = bin_residual as f64 ;

    if post_residual == 0 { score -= 900.0 ; }

    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if next_item_size == post_residual {
            score -= 700.0 ;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx ;
            score -= 250.0 * (1.0 - fill_after_next / cap) ;
            score += 0.4 * fill_after_next ;
            if fill_after_next >= nx * 0.5 && fill_after_next > 0.0 {
                score -= 40.0 * (fill_after_next / cap) ;
            }
            if fill_after_next == 0.0 { score -= 120.0 ; }
            // chain lookahead: residual that can still host the next item again
            if fill_after_next >= nx {
                score -= 60.0 * (1.0 - (fill_after_next - nx) / cap) ;
            }
            // prefer leaving residuals that match typical future leftovers
            if mean_residual > 0.0 {
                let dev = (fill_after_next - mean_residual).abs () / cap ;
                score += 30.0 * dev ;
            }
        } else {
            score += 0.6 * pr + 50.0 ;
            if next_item_size <= bin_residual { score += 8.0 ; }
            if (pr as u32) < next_item_size && pr < 0.15 * cap {
                score += 60.0 ;
            }
            if pr > 0.3 * cap && pr < nx {
                score += 25.0 ;
            }
            // dead-space penalty: leftover too small for anything typical
            if mean_residual > 0.0 && pr > 0.0 && pr < mean_residual * 0.35 {
                score += 45.0 ;
            }
        }
    }

    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap) ;
        if fitting_bins_count == 0 { score -= 200.0 ; }
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        score -= 4.0 * progress ;
        if fitting_bins_count > 0 && isz < 0.5 * cap { score += 25.0 ; }
        if fitting_bins_count > 2 { score += 120.0 ; }
        if fitting_bins_count > 0 && isz / cap > 0.6 { score += 15.0 ; }
        // open new bin only if no open bin leaves a residual close to the item
        if fitting_bins_count > 0 {
            let best_gap = mean_residual ;
            if best_gap > 0.0 && (res - isz).abs () <= isz * 0.15 {
                score += 40.0 ;
            }
        }
    }

    let tightness = isz / bin_residual . max (1) as f64 ;
    score -= 3.0 * tightness ;

    if pr > 0.0 && mean_residual > 0.0 {
        let ratio = pr / mean_residual ;
        if ratio > 0.5 && ratio < 2.0 { score -= 10.0 ; }
        else if pr > mean_residual * 3.0 { score += 12.0 * (ratio - 3.0).min (5.0) ; }
    }

    if post_residual > 0 && post_residual < 20 { score -= 15.0 ; }
    if post_residual >= 20 && post_residual < 40 && post_residual < next_item_size as u32 {
        score -= 6.0 ;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 6.0 ; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 * (1.0 - dead / 10.0);
        } else {
            // Wasted space penalty grows for mid-range leftovers.
            score += 0.08 * dead;
        }
    }

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item would fit into the post residual, reward;
    // if post residual is just barely too small for the next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // More attractive early in the stream (long horizon amortizes bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // Less attractive if many bins are already open and fit.
        if fitting_bins_count > 0 {
            score += 8.0 + 2.0 * fitting_bins_count as f64;
        }
        // If the next item is large, a fresh bin preserves flexibility.
        if next_item_size > item_size {
            score -= 5.0;
        }
    }

    // Coupling with global state: placing into a bin whose residual is far
    // above the mean residual helps consolidate open bins.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Slight preference for filling bins with large residuals late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    let mut score = pr * (0.6 + 0.8 * poly);

    // Penalize dead space more sharply as stream progresses
    score += (norm_pr * norm_pr) * cap * (0.2 + 0.6 * progress * progress);

    // Reward tight fits (small post residual) smoothly
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * 0.5;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = (pr - ni) / cap;
        if diff >= 0.0 {
            score -= diff * diff * 30.0;
        } else {
            score += (-diff) * 20.0;
        }
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += (open_bins_count as f64).ln() * 2.0 * (mean_residual / cap).abs();

    // New-bin candidate: keep it attractive only when fit is poor
    if bin_residual == bin_capacity {
        score += 5.0 + 30.0 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable" class
    // (large enough to fit typical items) are rewarded; tiny dead-space leftovers penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit is ideal
    } else {
