        if pr < 10 {
            score += 25.0;
        }
        // harmonic class via integer division thresholds: leftover that can still
        // host a mid-sized item (>=20) is valuable
        if pr >= 20 {
            score -= 8.0;
        }
        if pr >= 35 {
            score -= 6.0;
        }
        if pr >= 50 {
            score -= 6.0;
        }
    }

    // Next-item compatibility: reward leftovers that can host the lookahead item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 12.0;
        // exact-class match: leftover leaves room for next item plus small slack
        let slack = pr - next_item_size;
        if slack <= 10 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // leftover cannot host next item: mild penalty scaled by how close it was
        let gap = (next_item_size - pr) as f64;
        score += (gap / 20.0).min(10.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if pr == 0 {
            score -= 10.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    // and mean residual is high (fragmentation already exists).
    if bin_residual == bin_capacity {
        let base = 20.0 + 2.0 * open_bins_count as f64;
        let frag = ((mean_residual - item_size as f64).max(0.0)) * 0.3;
        score += base + frag;
        // early in the stream, new bins are cheap; later, avoid them
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // if next item is huge, a fresh bin is actually attractive
        if next_item_size >= 60 {
            score -= 18.0;
        }
    }

    // Prefer tighter fills: waste ratio penalty
    score += (item_size as f64 / bin_residual.max(1) as f64) * -4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
