    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
        } else {
            score += 0.6 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score = -1000.0;
        } else {
            score += 30.0 * (1.0 - isz / cap);
            if fitting_bins_count == 0 {
                score -= 200.0;
            }
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 4.0 * progress;
            // Small items fit anywhere; prefer opening fresh bins for big items
            // only when existing bins are fragmented.
            if fitting_bins_count > 0 && isz < 0.5 * cap {
                score += 25.0;
            }
            if (post_residual as f64) > mean_residual * (0.5 + progress) {
                score -= 20.0;
            }
        }
    }

    // Tightness pressure: prefer bins where the item fills most of the residual.
    let tightness = isz / bin_residual.max(1) as f64;
    score -= 3.0 * tightness;

    // Tiny dead space is nearly a perfect fit.
    if post_residual > 0 && post_residual < 20 {
        score -= 15.0;
    }

    // Mild consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the smallest plausible item (>=1),
    // but practically we penalize gaps that are small relative to capacity.
    if post_residual > 0 {
        let gap = post_residual as f64;
        let cap = bin_capacity as f64;
        if gap < 10.0 {
            // Completely unusable sliver: strong penalty.
            score += 40.0 * (10.0 - gap) / 10.0;
        } else if gap < 20.0 {
            // Marginal gap: moderate penalty (hard to fill later).
            score += 15.0 * (20.0 - gap) / 10.0;
        }
        // Reward near-perfect fills superlinearly.
        score -= 30.0 * (1.0 - gap / cap).powi(6);
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (sets up a chain of tight placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to how tight it is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will not fit here: slight penalty for stranding space.
            score += 5.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize spreading across many bins; encourage filling
    // existing bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + progress);

    // Prefer bins tighter than the mean residual (fill the fullest bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many items remain
        // or open bins are crowded.
        let crowd = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            1.0
        };
        score += 25.0 - 15.0 * crowd - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fill: overwhelming bonus (existing bin still beats a fresh perfect
    // fill because the new-bin penalty below is applied afterwards).
    if post_residual == 0 {
        score -= 100.0;
    }

    if is_new_bin {
        // Base cost of opening a new bin: prefer reusing open bins when possible.
        score += 20.0;

        // Opening a bin late in the stream leaves less opportunity to amortize
        // its empty space, so penalize progressively more with progress.
        score += 30.0 * progress;

        if fitting_bins_count > 0 {
            // Real alternatives exist; a new bin is a genuine waste.
            score += 15.0 * fitting_bins_count as f64;
        } else {
            // No open bin can take the item: the new bin is the only option.
            score -= 40.0;
        }

        // Large items legitimately justify a fresh bin.
        if item_size as f64 > 0.7 * cap {
            score -= 10.0;
        }
    } else {
        // Last-chance bin: strongly prefer consuming it over opening a new bin,
        // unless the resulting dead space is catastrophic (lookahead term below).
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        if next > 0.0 {
            if next <= post {
                // Aggressive 2-step match: the next item fits into this bin's
                // leftover. Reward the placement; reward an exact 2-step fill most.
                let post2 = post - next;
                score -= 12.0 - post2.min(30.0) * 0.1;
                if post2 == 0.0 {
                    score -= 8.0;
                }
            } else {
                // Dead space: the leftover is too small for the lookahead item.
                // Penalize proportionally to how much of it is stranded.
                let gap = next - post;
                score += gap.min(40.0) * 0.25;
            }
        }

        // Relative-to-mean coupling: mildly prefer consuming bins whose residual
        // is above average (keep tight bins in reserve for small arrivals).
        score -= (bin_residual as f64 - mean_residual).clamp(-30.0, 30.0) * 0.15;

        // Tiny unusable leftover is bad regardless of what the lookahead says.
        if post > 0.0 && post < 5.0 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let isz = item_size as f64 ;
    let res = bin_residual as f64 ;

    if post_residual == 0 { score -= 900.0 ; }

    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if next_item_size == post_residual {
            score -= 700.0 ;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx ;
            score -= 250.0 * (1.0 - fill_after_next / cap) ;
            score += 0.4 * fill_after_next ;
            if fill_after_next >= nx * 0.5 && fill_after_next > 0.0 {
                score -= 40.0 * (fill_after_next / cap) ;
            }
            if fill_after_next == 0.0 { score -= 120.0 ; }
            // chain lookahead: residual can host the next item again
            if fill_after_next >= nx {
                score -= 60.0 * (1.0 - (fill_after_next - nx) / cap) ;
            }
            // prefer residuals matching typical future leftovers
            if mean_residual > 0.0 {
                let dev = (fill_after_next - mean_residual).abs () / cap ;
                score += 30.0 * dev ;
            }
        } else {
            score += 0.6 * pr + 50.0 ;
            if next_item_size <= bin_residual { score += 8.0 ; }
            if (pr as u32) < next_item_size && pr < 0.15 * cap {
                score += 60.0 ;
            }
            if pr > 0.3 * cap && pr < nx {
                score += 25.0 ;
            }
            // dead-space penalty: leftover too small for anything typical
            if mean_residual > 0.0 && pr > 0.0 && pr < mean_residual * 0.35 {
                score += 45.0 ;
            }
        }
    }

    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap) ;
        if fitting_bins_count == 0 { score -= 200.0 ; }
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        score -= 4.0 * progress ;
        if fitting_bins_count > 0 && isz < 0.5 * cap { score += 25.0 ; }
        if fitting_bins_count > 2 { score += 120.0 ; }
        if fitting_bins_count > 0 && isz / cap > 0.6 { score += 15.0 ; }
        // open new bin only if no open bin leaves a residual close to the item
        if fitting_bins_count > 0 {
            if mean_residual > 0.0 && (res - isz).abs () <= isz * 0.15 {
                score += 40.0 ;
            }
        }
        // late stream: discourage opening extra bins when many fit
        if fitting_bins_count >= 3 {
            score += 60.0 * (1.0 - progress) ;
        }
    }

    let tightness = isz / bin_residual . max (1) as f64 ;
    score -= 3.0 * tightness ;

    if pr > 0.0 && mean_residual > 0.0 {
        let ratio = pr / mean_residual ;
        if ratio > 0.5 && ratio < 2.0 { score -= 10.0 ; }
        else if pr > mean_residual * 3.0 { score += 12.0 * (ratio - 3.0).min (5.0) ; }
    }

    if post_residual > 0 && post_residual < 20 { score -= 15.0 ; }
    if post_residual >= 20 && post_residual < 40 && post_residual < next_item_size as u32 {
        score -= 6.0 ;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 6.0 ; }

    // reward near-perfect fills even when not exactly zero
    if pr > 0.0 && pr < 5.0 { score -= 25.0 ; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, heavily reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 5.0;
        }
    } else {
        // Last item: prefer filling bins as fully as possible.
        score -= 30.0 * tightness;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins are crowded (low mean residual) or many bins are open.
    if bin_residual == bin_capacity {
        let crowd = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing residuals are large (good space available).
        score += 20.0 + 60.0 * crowd;
        // Slight discount late in the stream when consolidation matters less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If item is huge, new bin is often fine.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild preference for placing into bins with below-average residual
    // (conserves large residuals for large future items).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Penalize opening many bins with large residuals (fragmentation guard).
    if open_bins_count > 4 && bin_residual == bin_capacity {
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with quadratic sharpening
    let mut score = pr as f64 * (1.0 + fit_norm * fit_norm);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tight packing matters less; late, dead space is heavily penalized
    let coupling = 2.0 * progress * (1.0 - progress) + progress * progress * progress;
    score -= coupling * (cap - pr) * 0.5;

    // Penalize bins that are far from the mean residual (outliers waste space)
    score += (pr - mean_residual).abs() * 0.3;

    // Reward using a bin that is the last chance to fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        let fit_quality = 1.0 - diff / cap;
        if fit_quality > 0.0 {
            score -= 20.0 * fit_quality * fit_quality;
        }
        // If next item cannot fit here, mild penalty for leaving awkward residual
        if nxt > pr {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Discourage opening too many bins when plenty of open ones exist
    score += open_bins_count as f64 * 0.15;

    // New-bin candidate: make it moderately attractive only when current bin fits are poor
    if bin_residual == bin_capacity {
        let best_possible = pr; // residual 0 if item fits perfectly elsewhere
        score += 10.0 + best_possible * 0.1;
        if progress > 0.8 {
            score -= 8.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "reusable" residue classes
    // (multiples of 10 up to ~30) are favored; tiny dead space is penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit: best possible outcome
    } else if pr <= 10 {
        score += 25.0; // nearly unusable sliver -> dead space penalty
    } else if pr <= 30 {
        score -= 12.0; // sweet spot: leftover can host small items
    }

    // Modulo-10 harmony: leftover divisible by 10 pairs cleanly with decile item sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0; // chain placement possible
            // Extra reward when next item exactly fills the residue class
            if next_item_size == pr {
                score -= 20.0;
            } else if pr - next_item_size <= 10 {
                score += 8.0; // would create a sliver after chaining
            }
        } else {
            score += 5.0; // next item cannot use this bin anyway
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item is huge
    // or all existing fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 35.0;
        if item_size > bin_capacity * 2 / 3 {
            new_bin_penalty -= 10.0; // big items pair well with fresh bins
        }
        if post_residual <= 10 {
            new_bin_penalty += 20.0; // would leave a sliver in a fresh bin
        }
        // Late in the stream, prefer closing out existing bins.
        new_bin_penalty += 15.0 * progress;
        score += new_bin_penalty;
    }

    // Prefer bins tighter than average (best-fit flavor) when many bins are open.
    if open_bins_count > 1 {
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Mild preference for fuller bins overall.
    score += 0.05 * (bin_capacity - bin_residual) as f64 * -1.0 / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strict dead-space avoidance archetype with open-bin pressure.
    let mut score = post_residual as f64;

    // Penalize small unusable gaps much harder than proportional space.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0; // dead space spike
    }
    // Post-residual below the smallest item is pure waste.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 15.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // Penalize leaving a gap the next item cannot use at all.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins unless the fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: empty bin should only win if fit is poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
        // Opening a new bin is fine early or when many bins already open.
        score -= open_bins_count as f64 * 0.8;
    }

    // Slight preference for bins below mean residual (balance load).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward when the next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-chain: strongly reward.
            score -= 40.0 + 20.0 * progress;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.15;
        } else {
            // Next item won't fit: penalize wasted chain opportunity,
            // scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 + miss * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New empty bin candidate: penalize mildly so it's chosen only when
    // no open bin offers a decent fit, but reward it when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).min(1.0)
        } else { 0.0 };
        score += 20.0 - 35.0 * crowding;
    }

    // Slight preference for compacting bins early in the stream.
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
