        // mean residual is high (fragmentation control).
        let open_f = open_bins_count as f64;
        if mean_residual > 30.0 && open_f > 2.0 {
            score += 0.05 * open_f;
        }
    }

    // Discourage leaving residuals in the awkward 40..60 band that few items fit.
    if post_residual >= 40 && post_residual <= 60 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr * (1.0 + poly);

    // Penalize dead space more sharply as stream progresses
    score += (pr * pr) * (0.001 + 0.004 * progress * progress);

    // Reward tight fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 10.0 * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item can use post_residual
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0 * (1.0 - progress);
        } else {
            let waste = next_item_size as f64 - pr;
            score += waste * 0.15 * (0.5 + progress);
        }
    }

    // New-bin candidate: mild penalty early, decreasing later
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Coupling with mean residual across open bins
    score += (mean_residual - pr).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes are more reusable. Reward "harmonic" residuals.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 6.0;
            }
        }
        if pr % 5 == 0 {
            harmony += 2.0;
        }
        score -= harmony;
    } else {
        // Perfect fit: extremely desirable.
        score -= 60.0;
    }

    // Dead-space penalty: residual too small for the smallest item class.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // reward strongly (chained harmonic fit).
    if next_item_size > 0 && next_item_size == pr {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // reward proportional leftover harmony after next placement
        let pr2 = pr - next_item_size;
        if pr2 % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // next item would need another bin; mildly penalize wasting residual
        score += (pr as f64) * 0.1;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item
    // is large and existing residuals are tight (mean residual small).
    if bin_residual == bin_capacity {
        score += 15.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < item_size as f64 * 0.6;
        if !tight {
            score += 20.0;
        } else {
            score -= 10.0 * (1.0 - progress);
        }
        // Large items pair better with a fresh bin.
        if item_size >= 60 {
            score -= 12.0;
        }
    }

    // Prefer tighter bins when many bins are open (reduce bin spread).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Modulo threshold on item size: items in "awkward" classes (e.g. 30,70)
    // pack better into bins whose residual shares the same class.
    if bin_residual % 10 == item_size % 10 && pr > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps in (0,10) are essentially unusable (min item = 10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer packing tighter
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: only attractive when current bin would leave big waste
    // or when no good option exists; penalize default new-bin slightly.
    if bin_residual == bin_capacity {
        score += 12.0;
        // allow new bin when the item is large relative to residual elsewhere
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mild phase pressure: late in stream, tighten packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Prefer bins below mean residual (tighter bins get filled first)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item's size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match: next item fits with small slack left after it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 40.0 * (1.0 - slack_after_next as f64 / 50.0).max(0.0);
    }

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (next_item_size - post_residual) as f64 / 50.0;
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Relative-to-mean adjustment: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Early in stream: encourage packing into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 55.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item can use: items range 1..=100,
    // so residual below ~ smallest plausible item is nearly unusable.
    if post_residual < 10 {
        score += 25.0; // hard penalty for near-dead space
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        // But if the fit creates dead space, soften the bonus.
        if post_residual < 15 {
            score += 15.0;
        }
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            // Perfect chaining: post residual exactly matches next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving a big odd gap.
            score += 0.05 * post_residual as f64;
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are underutilized
        // and late in the stream.
        score += 20.0 + 0.15 * mean_residual + 15.0 * progress;
        // Early in the stream with few bins, opening new bins is cheap.
        score -= 10.0 * (1.0 - progress) * (1.0 - open_bins_count.min(20) as f64 / 20.0);
    } else {
        // Existing bin: reward using bins when mean residual is high (fragmented state).
        score -= 0.03 * mean_residual;
        // Late in the stream, filling existing bins matters more.
        score -= 6.0 * progress;
    }

    // Small preference for balancing: avoid always dumping into the emptiest bin.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post residual) mildly; later, penalize
    // large residuals more strongly to avoid dead space accumulation.
    let poly = x * x * (1.0 - progress) + x * x * x * progress;
    score += 60.0 * poly;

    // Smooth interaction: large residual relative to mean residual is
    // attractive (a bin with lots of room absorbs the item well).
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        score -= 8.0 * (ratio / (1.0 + ratio));
    }

    // Last-chance bin: smooth sigmoidal reward as fitting bins become scarce.
    let scarcity = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).max(0.0));
    score -= 15.0 * scarcity * (1.0 - x);

    // Lookahead: reward if next item can fit into post residual (smooth kernel).
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64) / cap;
        let kernel = if fits > 0.0 { fits * (2.0 - fits).max(0.0) } else { 0.0 };
        score -= 10.0 * kernel * (0.5 + 0.5 * progress);
    }

    // Mild penalty for proliferation of open bins, scaled by progress.
    score += 0.5 * open_bins_count as f64 * (0.25 + 0.75 * progress);

    // New-bin candidate: make it moderately attractive only when residual is
    // full capacity, so tight existing fits still win.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction classes. Small classes (0..=10) are dead space -> penalize.
    let class = (post_residual * 4) / bin_capacity; // 0..3 harmonic class
    let class_penalty = match class {
        0 => 12.0,  // tiny unusable leftover
        1 => 5.0,   // awkward quarter-class
        2 => 1.5,   // half-class, still useful for mid items
        _ => 0.0,   // large residual, flexible
    };
    score += class_penalty;

    // Perfect / near-perfect fit rewards (harmonic alignment with capacity).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    } else if post_residual <= 10 {
        score -= 9.0;
    }

    // Modulo arithmetic on next_item_size: does the next item fit harmonically
    // into the post-residual class?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u64) <= (post_residual as u64) {
            // Next item nests perfectly -> strong reward.
            if post_residual - next_item_size <= 5 {
                score -= 22.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead-space risk
            // proportionally to how large the leftover is relative to next item.
            score += 4.0 + (post_residual as f64) * 0.05;
        }
        // Harmonic residue of next item against capacity (mod classes)
        let nxt_mod = next_item_size % 10;
        if nxt_mod == 0 && (bin_residual % 10) == item_size % 10 {
            score -= 3.0; // aligned decimal classes
        }
        let _ = nxt;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline; discourage opening a new bin
    // when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + (open_bins_count as f64) * 0.1;
        if fitting_bins_count > 0 {
            score += 15.0; // existing bins can host -> deprioritize new bin
        }
        if next_item_size > 0 && (next_item_size as u64) <= (bin_capacity as u64) / 2 {
            score -= 5.0; // next item small, a fresh bin stays flexible
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (post_residual as f64) / cap;

    // Slight preference for bins tighter than the mean residual (good packing).
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;

    if post_residual == 0 {
        score -= 900.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
            // reward near-exact two-item chain fills
            if fill_after_next < 12.0 {
                score -= 40.0;
            }
        } else {
            score += 0.6 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
        }
    }

    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
        if fitting_bins_count > 0 && isz < 0.5 * cap {
            score += 25.0;
        }
        // discourage opening a new bin when many open bins still fit the item
        if fitting_bins_count >= 2 {
            score += 55.0;
        } else if fitting_bins_count == 1 {
            score += 18.0;
        }
    }

    let tightness = isz / bin_residual.max(1) as f64;
    score -= 3.0 * tightness;

    // stronger pressure on small dead space
    if post_residual > 0 && post_residual < 20 {
        score -= 15.0 + 1.5 * (20.0 - pr);
    }

    // mild penalty for leaving residuals that no plausible item can use
    if post_residual > 0 && post_residual < next_item_size as f64 && next_item_size > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below half capacity are nearly useless
    // (items are 1..=100, but typical stream items leave small gaps unusable).
    if post_residual > 0 && post_residual < bin_capacity / 2 {
        // Quadratic penalty growing as the gap shrinks toward unusability
        let gap = post_residual as f64;
        score += 40.0 * ((bin_capacity as f64 / 2.0 - gap) / (bin_capacity as f64 / 2.0)).powi(2);
    }

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward filling most of the bin (post_residual small relative to capacity)
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage spreading across many bins
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would NOT fit in post residual but would fit an empty bin,
    // penalize blocking the stream
    if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_capacity {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous, easier to pack later)
    let resid_f = post_residual as f64;
    score += 0.1 * (resid_f - mean_residual).abs();

    // Late in stream: be more aggressive about closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (resid_f / bin_capacity as f64);

    // New-bin candidate: mild penalty so open bins are preferred unless fit is bad
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect 2-step fit: post_residual == next_item_size -> big reward.
        if diff == 0.0 {
            score -= 40.0;
        } else if post_residual as f64 >= nxt {
            // Next item still fits: reward proportionally to closeness.
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit in leftover: penalize dead space, worse when gap small.
            score += 10.0 + 5.0 * (1.0 - diff / (bin_capacity as f64));
        }

        // Also check whether the next item fits the bin's CURRENT residual (alternative pairing).
        if (bin_residual as f64) >= nxt + item_size as f64 {
            score -= 3.0;
        }
    } else {
        // Last item: minimize leftover.
        score += 5.0;
    }

    // Relative-to-mean coupling: bins tighter than average are precious; prefer to fill them.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 6.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 4.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Many options: slight penalty to prefer best-fit discrimination.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Discourage near-zero dead space creation being wasted (tiny unusable slivers)
    // unless a new bin is preferable anyway.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Early in the stream, allow slightly more freedom to open bins; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mild penalty proportional to how full the bin already is relative to capacity,
    // encouraging balanced residual usage across bins.
    score += 2.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when open bins are quite full on average.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 25.0 * avg_fill - 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;

    // Perfect fit: overwhelmingly good.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Dead-space spike for tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 12.0;
    }

    // Tightness reward.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 15.0;
    let fill_ratio = isz / bin_residual.max(1) as f64;
    score -= 3.0 * fill_ratio;

    // Lookahead on the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
        } else {
