            if next_item_size <= bin_residual {
                score += 8.0;
            }
        }
    }

    // Last-chance pressure: only fitting bin, keep it alive.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // New-bin candidate: only wins when no open bin fits or fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        score -= 4.0 * progress;
        if fitting_bins_count > 0 && isz < 0.5 * cap {
            score += 25.0;
        }
        if pr > mean_residual {
            score += 10.0;
        }
        score -= open_bins_count as f64 * 0.8;
    }

    // Balance toward below-mean residual bins.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual is good, but dead space that
    // cannot fit even the smallest plausible item is worse than it looks.
    let dead_space = if post_residual < 10 { 1.0 } else { 0.0 };
    score += dead_space * 15.0;

    // Lookahead: penalize placements that leave the next item homeless.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus for leaving room for the next item (chaining).
            score -= 6.0;
            // Extra bonus if next item fits *exactly snugly*.
            let snug = (post_residual as f64 - next_item_size as f64).abs();
            if snug < 5.0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here afterwards: mild penalty scaled by
            // how much residual is wasted relative to capacity.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Crowding: if many bins are open, prefer consolidating into bins
    // with below-average residual (i.e., tighter bins).
    if open_bins_count > 1 {
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += rel * 8.0;
    }

    // Time horizon: early on, be more exploratory (favor new bins with
    // lots of residual for flexibility); late, be greedy (favor tight fits).
    let exploration = 1.0 - progress;
    score += exploration * (post_residual as f64 / bin_capacity as f64) * 5.0;
    score -= progress * (item_size as f64 / bin_capacity as f64) * 6.0;

    // New-bin candidate: keep it competitive only when existing bins fit
    // poorly (large post_residual among open bins). Its raw post_residual
    // is high, so add a mild stabilization term.
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * progress;
    }

    score
}

