pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post * (1.0 - progress) * (1.0 - progress);

    let mut score = poly * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 30.0 * (0.5 + progress);

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (1.0 + progress);
        } else {
            score -= (1.0 - (post - nxt) / cap) * 5.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Slight penalty for bins far below the mean residual (fragmentation).
    score += (mean_residual - post).abs() * 0.15 * progress;

    // Mild penalty for many open bins (encourage consolidation early).
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual mod 10 as "waste class".
    // Residuals that are small (<= 10) are nearly perfect; reward them.
    if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Penalize dead space in the awkward band 21..=39 (hard to fill later).
    if post_residual > 20 && post_residual < 40 {
        score += 20.0;
    }

    // Modulo-arithmetic coupling: if next item exactly fits post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Next item fits leaving a small harmonic residual (multiple of 10 classes).
    if next_item_size > 0 && next_item_size < post_residual {
        let nres = post_residual - next_item_size;
        if nres <= 10 {
            score -= 80.0;
        } else if nres <= 20 {
            score -= 30.0;
        }
        // Chain fit: item + next <= residual is a good packing.
        score -= 15.0;
    }
    // Next item won't fit here: mild penalty, scaled by how much it misses.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0 + ((next_item_size - post_residual) as f64).min(40.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
