    // New-bin candidate: penalize opening a bin unless current item is large
    // and would leave a usable residual (>= 20) or no open bin fits well.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 70.0;
        if post_residual >= 20 && post_residual <= 40 {
