pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;

    // Perfect fit: overwhelmingly good.
    if post_residual == 0 {
        score -= 900.0;
    }

    // Dead-space spike for tiny unusable gaps (scaled by item size).
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 7.0;
    }
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 12.0;
    }

    // Tightness reward.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 18.0;
    let fill_ratio = isz / bin_residual.max(1) as f64;
    score -= 3.5 * fill_ratio;

    // Lookahead on the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
            // Two-step chain: next item leaves room for a small residual.
            if fill_after_next > 0.0 && fill_after_next < 8.0 {
                score -= 6.0;
            }
        } else {
            score += 0.6 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
        }
    }

    // Last-chance pressure: only fitting bin, keep it alive.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // New-bin candidate: only wins when no open bin fits or fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        score -= 4.0 * progress;
        if fitting_bins_count > 0 && isz < 0.5 * cap {
            score += 28.0;
        }
        if pr > mean_residual {
            score += 10.0;
        }
        score -= open_bins_count as f64 * 0.8;
        // Avoid opening a bin for items that would leave a large stranded gap.
        if pr > 0.6 * cap && isz < 0.3 * cap {
            score += 15.0;
        }
    }

    // Balance toward below-mean residual bins.
    if (bin_residual as f64) < mean_residual {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly (wasted capacity grows quadratically).
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            score += 0.1 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Time horizon: early in the stream, encourage spreading (open bins) to build
    // flexibility; late in the stream, consolidate tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> favor consolidation
    // into bins below the mean residual (filling the emptier bins first balances).
    if open_bins_count > 2 && mean_residual > 0.0 {
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * diff;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * fit_gap * fit_gap;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_options = fitting_bins_count == 0
            || (fitting_bins_count == 1 && bin_residual >= bin_capacity);
        if poor_options {
            score -= 12.0;
        } else {
            // Opening a new bin wastes potential: penalize, scaled by open bins.
            score += 20.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (small post_residual), with a mild convexity
    // so very small residuals (dead space) are penalized smoothly.
    let tightness = pr / cap;                       // 0..1
    let mut score = tightness * (1.0 - 0.5 * tightness) * cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, leave room for future items (favor larger residuals slightly);
    // late in the stream, chase tight fits harder.
    let progress_coupling = (1.0 - progress) * (pr * pr) / cap - progress * (cap - pr) * (cap - pr) / cap;
    score += 0.15 * progress_coupling;

    // Lookahead: reward residuals that can still fit the next item,
    // penalize residuals that strand space just below the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * (1.0 - tightness);
    }

    // New-bin candidate: penalize mildly so open bins are preferred unless
    // they are all poor fits (their scores will be high due to dead space).
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Slight preference for bins with residuals near the mean (balance load).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into 5 fractional classes.
    let fifth = bin_capacity / 5;
    let post_class = post_residual / fifth; // 0..=5
    match post_class {
        0 => score -= 30.0, // near-perfect fill
        1 => score -= 18.0,
        2 => score -= 8.0,
        3 => score += 6.0,
        _ => score += 14.0, // large leftover: wasteful
    }

    // Modulo-10 harmonic: small dead space (residual % 10) is unusable for typical items.
    let dead = (post_residual % 10) as f64;
    score += dead * 1.5;

    // Reward if next item fits exactly into post_residual (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // integer-division coupling: how many copies of next item fit
            let copies = post_residual / next_item_size.max(1);
            score -= copies as f64 * 4.0;
        } else {
            score += 10.0; // next item cannot use this bin's remainder
        }
    } else {
        // last item: any fit is fine, prefer tightest
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // early in stream, allow more new bins to spread load
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer filling bins below mean residual (above-average fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 3.0;
    }

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
