pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the smallest
    // plausible item are essentially wasted; penalize them heavily.
    if post_residual < 10u32.min(bin_capacity) {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 40 {
        score += 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving a gap that is just barely too small for the next item
    // (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
    }
    // Reward a residual that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Last-chance bonus: this is the only open bin that fits; avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing
    // bins rather than spreading out.
    score += open_bins_count as f64 * 0.4;

    // Slight preference for tighter-than-average bins (consolidation).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate: make an empty bin attractive only when the current
    // fit is bad (large post_residual) and there are already many bins.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64;
        score -= 12.0 + bad_fit * 0.25 + (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact or near-exact fits (low post_residual).
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64).powi(2);

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize dead space that the next item cannot use.
            score += 5.0 + 0.05 * (post_residual as f64 - next_item_size as f64).abs();
        }
    } else {
        // Last item: prefer zero-waste fits strongly.
        score -= 6.0;
    }

    // Relative-to-mean coupling: bins tighter than average are attractive.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin, but allow it when the item
    // fits poorly everywhere else (large item, high waste potential).
    if bin_residual == bin_capacity {
        let waste_elsewhere = (bin_residual - item_size) as f64;
        score += 14.0 - 0.1 * item_size as f64;
        // If item is large, new bin keeps small residual flexible for future items.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
        let _ = waste_elsewhere;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
