            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
        } else {
            // Next item cannot use the leftover gap.
            score += 0.6 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
        }
    }

    // Tightness reward.
    let tightness = isz / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: discourage spreading.
    score += 4.0 * open_bins_count as f64;

    // Prefer tighter-than-mean bins.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: strong penalty for small items, mild
    // attraction for large items or when nothing fits anywhere.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
        if fitting_bins_count > 0 && isz < 0.5 * cap {
            score += 25.0;
        }
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Late-stream conservatism on leftover space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (pr / cap);

    // Small-gap flexibility bonus for near-exact residual fits.
    if post_residual > 0 && post_residual < 20 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 30.0;
    }
    // Unusable dead-space penalty (gap too small for any item >= 1... treat < 8 as waste)
    else if post_residual < 8 {
        score += 45.0 * (1.0 - post_residual as f64 / 8.0);
    }

    // Lookahead coupling: reward bins that can also host the next item,
    // penalize bins that strand a large residual unusable by the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 6.0 * progress;
        } else {
            score += 0.20 * (next_item_size as f64 - post_residual as f64).min(80.0);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // scaled down late in the stream when hoarding space matters more
    if fitting_bins_count == 1 {
        score -= 28.0 * (1.0 - 0.5 * progress);
    }

    // Global pressure: when open bins are collectively full (low mean residual),
    // discourage squeezing into them; encourage spreading load
    score += 0.10 * mean_residual;

    // New-bin candidate detection: residual == capacity
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap when existing bins are nearly full
        // or many bins are already open (load balancing)
        let scarcity = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 35.0 * (1.0 - scarcity);
        // Mild penalty so we don't proliferate bins early for small items
        score += 0.15 * item_size as f64 * (1.0 - progress);
        // If several bins already fit the item, opening a new one is wasteful
        if fitting_bins_count > 1 {
            score += 25.0 * fitting_bins_count.min(5) as f64;
        }
    }

    // Slight preference for bins with larger residual absorbing small items
    score -= 0.05 * bin_residual as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
