}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Leftovers that are "harmonically aligned"
    // with typical item sizes (multiples of 10) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction remaining

    // Penalize dead space that is too small to hold the smallest item (1..100 interface).
    if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64;
    }

    // Harmonic bucket reward: leftover in a "nice" class (>= half, quarter, etc.)
    if frac >= 0.5 {
        score -= 8.0;
    } else if frac >= 0.25 {
        score -= 3.0;
    } else if frac >= 0.1 {
        score += 2.0;
    } else {
        score += 6.0;
    }

    // Modulo alignment: leftover divisible by common item granularity (10)
    // is more likely to be filled by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: reward if next item fits the leftover exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot use this leftover: leftover likely wasted
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer filling the final fitting bin
    // rather than opening a new one, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual <= 10 {
            score -= 8.0; // near-perfect fill in last chance bin
        }
    }

    // New-bin candidate handling: only open a new bin when current bin
    // would leave a large unusable gap or many bins already fit well.
    if bin_residual == bin_capacity {
        // Brand-new bin: baseline attractiveness, slightly worse than a
        // good existing fit, better than a bad one.
        score -= 5.0;
        if item_size >= 50 {
            score -= 3.0; // big items fine in fresh bins
        }
    } else if post_residual > 60 && next_item_size > 0 && next_item_size > post_residual {
        // Existing bin would be badly stranded; new bin may be preferable.
        score += 4.0;
    }

    // Prefer consolidating into few bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Slight preference for tighter fits: reward small post_residual variance vs mean.
    if post < mean_residual {
        score -= 1.5;
    } else {
        score += 0.5 * (post - mean_residual) / cap;
    }

    // Progress term: later in stream, be greedier about exact fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (100.0 - post) / cap;

    score
}

