                score += 8.0;
            }
            if next_item_size > bin_residual && br < nx * 0.5 {
                score += 30.0 * (1.0 - pr / cap);
            }
            if fitting_bins_count > 2 && br > nx * 0.75 {
                score += 15.0 * (br / cap);
            }
            if fitting_bins_count <= 2 {
                let dev = (pr - mean_residual).abs();
                score += 0.8 * dev;
            }
        }
    }

    // New-bin candidate handling: fresh bin only attractive for large items.
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity / 2 {
            score -= 5.0;
        } else {
            score += 20.0 + 3.0 * open_bins_count as f64;
        }
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
