pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize leaving dead space that no plausible future item can use.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let small_item = if next_item_size > 0 { next_item_size.min(item_size) } else { 10 };
    if post_residual > 0 && (post_residual as f64) < small_item as f64 {
        score += 6.0 + 0.05 * post_residual as f64;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 1.5;
    }

    // Last-chance bin: strongly favor filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Prefer bins below mean residual (consolidate emptiness).
    let res = bin_residual as f64;
    if res > mean_residual {
        score += 0.03 * (res - mean_residual);
    } else {
        score -= 0.02 * (mean_residual - res);
    }

