        score -= 2.0 * (1.0 - t) + 0.05 * item_size as f64;
        score += 3.0 * crowd + 4.0 * t;
        // Never open a new bin when a near-perfect fit exists elsewhere.
        if post_residual == 0 && bin_residual == bin_capacity {
            score += 20.0;
        }
    } else {
        score -= 0.5 * crowd;
    }

    // Late-stream: push toward closing bins tightly.
    score += 4.0 * t * (post_residual as f64 / bin_capacity as f64);

