            if next_item_size <= bin_residual {
                score += 8.0;
            }
            if next_item_size > bin_residual && br < nx * 0.5 {
                score += 30.0 * (1.0 - pr / cap);
            }
            if fitting_bins_count > 2 && br > nx * 0.75 {
                score += 15.0 * (br / cap);
            }
            if fitting_bins_count <= 2 {
                let dev = (pr - mean_residual).abs();
                score += 0.8 * dev;
            }
            // Penalize leaving gaps slightly larger than the next item class.
            if pr > nx && pr < nx * 1.35 {
                score += 22.0;
            }
        }
    }

    // Last-chance pressure: only fitting bin, keep it alive.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // New-bin candidate: only wins when no open bin fits or fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        score -= 4.0 * progress;
        if fitting_bins_count > 0 && isz < 0.5 * cap {
            score += 28.0;
        }
        if pr > mean_residual {
            score += 10.0;
        }
        score -= open_bins_count as f64 * 0.8;
        if pr > 0.6 * cap && isz < 0.3 * cap {
            score += 15.0;
        }
        // Discourage opening a new bin when a decent existing fit exists.
        if fitting_bins_count > 0 && post_residual > 0 {
            let waste = pr;
            if waste <= cap * 0.15 {
                score += 160.0;
            } else {
                score += 25.0 + 0.35 * waste;
            }
        }
        // Late in the stream, strongly prefer consolidating into open bins.
        if progress > 0.55 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Never open a new bin for small items when many bins can host them.
        if fitting_bins_count > 3 && isz < 0.25 * cap {
            score += 45.0;
        }
        // Extra: refuse new bins when the best existing fit is very tight.
        if fitting_bins_count > 0 && pr <= 4.0 {
            score += 120.0;
        }
    }

    // Balance toward below-mean residual bins.
    if br < mean_residual {
        score -= 2.5;
    }

    // Waste-shape penalty: leave residuals that small/medium items can still reuse.
    if post_residual > 0 && post_residual < 25 {
        score += 0.8 * (25.0 - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize wasted residual, non-linearly (quadratic waste growth).
    let mut score = post * (1.0 + 0.004 * post);

    // Smooth non-linear coupling of waste with stream progress:
    // early on, waste is cheaper; later, tight packing matters more.
    let progress_coupling = post * post / cap * (0.5 + 1.5 * progress * progress);
    score += progress_coupling;

    // Reward near-perfect fits (small post_residual) with a smooth bump.
    let fit_quality = 1.0 - (post / cap);
    score -= 12.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild preference toward bins that keep alternatives open.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Penalize bins far from the mean residual (prefer balanced fills),
    // smoothly scaled by progress.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * deviation * (0.5 + progress);

    // Lookahead: reward leaving room for the next item when it exists.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - (slack / cap).min(1.0)) * (0.4 + 0.6 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space mildly.
        score += 4.0 * (item / cap);
    }

    // New-bin candidate handling: make opening a new bin costly early,
    // but allow it late when the fit into existing bins is poor.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5 && post_residual == bin_residual - item_size && bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 * (1.0 - progress) + 10.0;
        // If existing bins are very full on average, new bin is less bad.
        score -= 15.0 * (1.0 - (mean_residual / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let mut score = pr;

    // Perfect closure: best possible outcome.
    if post_residual == 0 {
        score -= 950.0;
    } else if post_residual < 10 {
        score += 70.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    let tightness = item_size as f64 / br.max(1.0);
    score -= 30.0 * tightness;

    // Open-bin pressure.
    score += 4.0 * open_bins_count as f64;

    // Prefer tighter-than-mean bins.
    if br < mean_residual {
        score -= 8.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: exact chain with next item is gold.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 750.0;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
            let dev = (fill_after_next - mean_residual).abs();
            score -= 12.0 * (1.0 - dev / cap).max(0.0);
            if fill_after_next == 0.0 {
                score -= 180.0;
            }
            if fill_after_next > 0.0 && fill_after_next < nx * 0.25 {
                score += 45.0;
            }
            if fill_after_next > 0.0 && fill_after_next >= nx * 0.25 && fill_after_next <= nx * 0.6 {
                score -= 20.0;
            }
            if fill_after_next > 0.0 && fill_after_next <= 8.0 {
                score -= 30.0;
            }
        } else {
            // dead space relative to known next item
            score += 0.7 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
            if next_item_size > bin_residual && br < nx * 0.5 {
                score += 35.0 * (1.0 - pr / cap);
            }
            if fitting_bins_count > 2 && br > nx * 0.75 {
                score += 18.0 * (br / cap);
            }
            if fitting_bins_count <= 2 {
                let dev = (pr - mean_residual).abs();
                score += 0.9 * dev;
            }
        }
    }

    // New-bin candidate handling: fresh bin only attractive for large items.
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        } else {
            score += 25.0 + 3.0 * open_bins_count as f64;
        }
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // Late in the stream, opening a fresh bin is riskier.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * progress;
    }

    // Slight stream-progression bias against wasteful residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into capacity-fraction bands.
    // Small post_residuals (tight fits) are valuable; large ones are wasteful.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer-division thresholds on post_residual create discrete classes.
    // class 0: pr <= 10 (near-perfect), class 1: <=25, class 2: <=50, else loose.
    let class = post_residual / 10;
    let class_bonus = match class {
        0 => -40.0,
        1 => -20.0,
        2 => -8.0,
        3 => 0.0,
        4 => 6.0,
        5 => 10.0,
        _ => 12.0,
    };
    score += class_bonus;

    // Non-linear tight-fit reward: quadratic decay of value as residual grows.
    score -= (1.0 - frac) * (1.0 - frac) * 15.0;

    // Modulo arithmetic on post_residual: residuals that are "harmonic"
    // divisors/multiples of common item sizes (10, 20, 25, 50) are reusable.
    let mod_bonus = if post_residual % 10 == 0 {
        -6.0
    } else if post_residual % 5 == 0 {
        -3.0
    } else if post_residual % 25 == 0 {
        -8.0
    } else {
        0.0
    };
    score += mod_bonus;

    // Lookahead: if next item fits exactly or well in post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer tighter fits (already encoded) but add mild spread penalty
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Prefer bins below mean residual (consolidating space) early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_gap = mean_residual - pr;
    score -= mean_gap * (0.3 + 0.4 * progress);

    // New-bin candidate (empty bin): penalize unless residual is very large
    // relative to typical need, i.e., only open new bin when it's genuinely better.
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
        // Opening a new bin is attractive if item is huge and would leave bad residue elsewhere
        if item_size >= 60 && post_residual >= 0 {
            score -= (item_size as f64 - 60.0) * 0.5;
        }
    }

    // Dead-space penalty: residuals below the minimum item size are unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    score
}

