pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward when the next item exactly fills the post residual (perfect chaining).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let gap = post - next;
            // Perfect fit chain: strong reward.
            if gap == 0.0 {
                score -= 45.0;
            } else {
                // Proportional reward for small gaps after chaining.
                score -= 30.0 * (1.0 - gap / post.max(1.0));
                // Penalize leaving dead space unusable by typical items.
                if gap < 10.0 {
                    score += (10.0 - gap) * 0.8;
                }
            }
        } else {
            // Next item cannot fit into post residual: mild penalty for tight packing here.
            score += (next - post) * 0.15;
        }

        // Reward if next item fits current residual exactly too (alternative chain).
        let resid = bin_residual as f64;
        if next <= resid && (resid - next) == post {
            score -= 5.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize near-empty usage of a fresh bin unless item is large.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score += 15.0 * (1.0 - fill);
        // But if no other bin fits well, allow new bin: handled by comparison.
    }

    // Penalize tiny post residuals (unusable dead space) unless zero.
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 1.2;
    }

    // Late in the stream, prefer tighter packing (fewer wasted residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let mut score = pr;

    // Perfect closure: best possible outcome.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    let tightness = item_size as f64 / br.max(1.0);
    score -= 25.0 * tightness;

    // Open-bin pressure.
    score += 4.0 * open_bins_count as f64;

    // Prefer tighter-than-mean bins.
    if br < mean_residual {
        score -= 6.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: exact chain with next item is gold.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0;
        } else if post_residual >= next_item_size {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
            let dev = (fill_after_next - mean_residual).abs();
            score -= 12.0 * (1.0 - dev / cap).max(0.0);
            if fill_after_next == 0.0 {
                score -= 150.0;
            }
            if fill_after_next > 0.0 && fill_after_next < nx * 0.25 {
                score += 40.0;
            }
            if fill_after_next > 0.0 && fill_after_next >= nx * 0.25 && fill_after_next <= nx * 0.6 {
                score -= 18.0;
            }
            if fill_after_next > 0.0 && fill_after_next <= 8.0 {
                score -= 25.0;
            }
            // Two-step chain: item + next fills bin almost exactly.
            if (item_size as f64 + nx) / br > 0.92 {
                score -= 20.0;
            }
        } else {
            // dead space relative to known next item
            score += 0.6 * pr + 40.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
            if next_item_size > bin_residual && br < nx * 0.5 {
                score += 30.0 * (1.0 - pr / cap);
            }
            if fitting_bins_count > 2 && br > nx * 0.75 {
                score += 15.0 * (br / cap);
            }
            if fitting_bins_count <= 2 {
                let dev = (pr - mean_residual).abs();
                score += 0.8 * dev;
            }
            // Penalize large residual relative to next item need.
            if pr > nx * 1.5 {
                score += 0.5 * (pr - nx * 1.5);
            }
        }
    }

    // New-bin candidate handling: fresh bin only attractive for large items.
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity / 2 {
            score -= 5.0;
        } else {
            score += 20.0 + 3.0 * open_bins_count as f64;
        }
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
        // Late in the stream, opening a fresh bin is riskier.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Slight stream-progression bias against wasteful residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin;
    // if the next item would fit better elsewhere, slight penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 12.0 * chain_fit;
        } else {
            score += 6.0;
        }
    }

    // Prefer bins with residual above the mean (keep balanced bins flexible),
    // mildly scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.08 * dev * (1.0 - 0.5 * progress);

    // Late in the stream, be more conservative: penalize opening new bins
    // and favor consolidating into existing ones.
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and would leave a very tight fit, or no decent alternative exists.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - item_ratio);
        if fitting_bins_count > 0 && item_ratio < 0.5 {
            score += 15.0;
        }
        // With many open bins, opening yet another is costly.
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap; // in [0,1]

    // Non-linear polynomial coupling: penalize mid-range dead space quadratically,
    // scaled by stream progress (late stream => tighter packing desired).
    let dead_space_penalty = 4.0 * norm_post * (1.0 - norm_post); // peaks at 0.5 residual
    score += dead_space_penalty * (1.0 + 2.0 * progress) * cap * 0.25;

    // Reward near-perfect fits with cubic shaping
    let fit_quality = 1.0 - norm_post;
    score -= fit_quality * fit_quality * fit_quality * (item_size as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * 0.6;
    } else if fitting_bins_count > 1 {
        // Mild competition bonus proportional to scarcity
        score -= cap * 0.1 / fitting_bins_count as f64;
    }

    // Lookahead coupling: if next item fits into the resulting post_residual,
    // reward this placement (chaining future items into same bin).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack_after_next = pr - next_item_size as f64;
        score -= 8.0 * (1.0 - slack_after_next / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving fragmented residual
        score += 4.0 * norm_post * progress;
    }

    // Mean residual coupling: placing into a bin below mean residual helps
    // balance load; smooth quadratic attraction toward mean.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Open bins pressure: many open bins => prefer consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 2.0;

    // New-bin candidate handling: empty bin gets a moderate penalty so it is
    // chosen only when open bins would waste too much space.
    if bin_residual == bin_capacity {
        score += cap * 0.9 * (1.0 - progress * 0.3);
        // but if item is large relative to capacity, opening a fresh bin is fine
        score -= (item_size as f64 / cap) * cap * 0.35;
    }

    score
}

