pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands on "usable"
    // classes (multiples of small divisors) are more valuable, reward them.
    let pr = post_residual;
    if pr > 0 {
        // Class bonus: residual divisible by 10 or 25 keeps future pairing options.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Penalize odd residuals (harder to pair with even-ish items).
        if pr % 2 == 1 {
            score += 2.0;
        }
        // Dead-space penalty: tiny residuals are wasted capacity.
        if pr < 5 {
            score += 12.0;
        } else if pr < 10 {
            score += 6.0;
        }
