    // this is a harmonic pair — reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // Next item still fits; prefer leaving a clean class residual.
            let rem2 = pr - next_item_size;
            if rem2 % 10 == 0 {
                score -= 8.0;
            } else if rem2 % 5 == 0 {
                score -= 4.0;
            }
            if rem2 < 5 && rem2 > 0 {
                score += 5.0;
            }
        } else {
            // Next item won't fit here: mildly penalize blocking bins that
            // would otherwise stay flexible, unless this is the only fitting bin.
            if fitting_bins_count > 1 {
                score += 4.0;
            } else {
                score -= 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit into open bins would create large dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = mean_residual / bin_capacity as f64;
        // Penalize new bins early and when open bins still have room.
        score += 30.0 + 40.0 * (1.0 - progress) + 25.0 * (1.0 - crowdedness);
        // If the item is huge relative to capacity, a fresh bin is fine.
        if item_size >= 70 {
            score -= 20.0;
        }
        // If no open bin can fit at all, new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer tighter fits generally: relative waste term.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * waste_frac * waste_frac;

    // Mild preference for fuller bins as stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - waste_frac);

    score
}

