pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize residuals that are too small
    // to be usable by typical future items (dead zone < 20).
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 3.0;
    }
    if post_residual == 0 {
        // Perfect fit reward
        score -= 25.0;
    }

    // Penalize creating a gap that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size as u32 {
        score -= 5.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += (open_bins_count as f64) * 0.7;

    // Last chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Mild alignment with mean residual: prefer bins with residuals close to mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins that end up (nearly) full.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 500.0;
    }

    // 2-step lookahead: reward post_residual that matches next item exactly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        if gap < 1.0 {
            score -= 300.0;
        } else if gap <= 10.0 {
            score -= 150.0 - gap * 10.0;
        }
        // Penalize dead space the next item cannot use.
        if pr < n {
            score += (n - pr) * 2.0;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than the mean.
    score += (pr - mean_residual) * 0.5;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when it enables a great 2-step chain
    // (item + next item fill the fresh bin) or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let base = cap - score; // recover baseline; re-anchor new-bin score
        let mut new_score = cap - pr; // = item_size, neutral tightness measure
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let chain_waste = (bin_capacity - item_size - next_item_size) as f64;
            new_score = chain_waste * 1.5 - 100.0;
        }
        // Open new bin only if existing bins are fragmented / poor fits.
        let fragmentation = open_bins_count as f64 * (mean_residual / cap).max(0.0);
        new_score += 50.0 - fragmentation * 10.0;
