    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.1 * (item / cap) * 100.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more strongly when
    // open bins exist with adequate room and many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_f = open_bins_count as f64;
