        let mut new_bin_penalty = 15.0 + 2.0 * open_f.sqrt() * 10.0;
        // Early in the stream, opening bins is cheaper (builds a portfolio);
        // late in the stream, consolidation matters more.
        new_bin_penalty *= 0.5 + 1.5 * progress;
        // If mean residual across open bins is large, opening a new bin wastes potential.
        new_bin_penalty += 0.4 * mean_residual;
        // If item is huge relative to capacity, a fresh bin is more justified.
        new_bin_penalty -= 0.3 * item;
