    let tightness = 1.0 - (pr / br.max(1.0));
    score -= tightness * 18.0;
    let fill_ratio = isz / br.max(1.0);
    score -= 3.5 * fill_ratio;

    // Lookahead on the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
            let dev = (fill_after_next - mean_residual).abs();
            score -= 12.0 * (1.0 - dev / cap).max(0.0);
            if fill_after_next == 0.0 {
                score -= 150.0;
            }
            if fill_after_next > 0.0 && fill_after_next < nx * 0.25 {
                score += 40.0;
            }
            if fill_after_next > 0.0 && fill_after_next >= nx * 0.25 && fill_after_next <= nx * 0.6 {
                score -= 18.0;
            }
            if fill_after_next > 0.0 && fill_after_next <= 8.0 {
                score -= 25.0;
            }
        } else {
            score += 0.6 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
            if next_item_size > bin_residual && br < nx * 0.5 {
                score += 30.0 * (1.0 - pr / cap);
            }
            if fitting_bins_count > 2 && br > nx * 0.75 {
                score += 15.0 * (br / cap);
            }
            if fitting_bins_count <= 2 {
                let dev = (pr - mean_residual).abs();
                score += 0.8 * dev;
            }
            // Penalize leaving gaps slightly larger than the next item class.
            if pr > nx && pr < nx * 1.35 {
                score += 22.0;
            }
            // New: reward bins whose post-residual remains a useful target for
            // the next item's class even when it does not fit right now.
            if pr >= nx * 1.35 && pr <= nx * 2.0 {
                score -= 10.0;
            }
        }
    }

    // Last-chance pressure: only fitting bin, keep it alive.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // New-bin candidate: only wins when no open bin fits or fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - isz / cap);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        score -= 4.0 * progress;
        if fitting_bins_count > 0 && isz < 0.5 * cap {
            score += 28.0;
        }
        if pr > mean_residual {
            score += 10.0;
        }
        score -= open_bins_count as f64 * 0.8;
        if pr > 0.6 * cap && isz < 0.3 * cap {
            score += 15.0;
        }
        // Discourage opening a new bin when a decent existing fit exists.
        if fitting_bins_count > 0 && post_residual > 0 {
            let waste = pr;
            if waste <= cap * 0.15 {
                score += 160.0;
            } else {
                score += 25.0 + 0.35 * waste;
            }
        }
        // Late in the stream, strongly prefer consolidating into open bins.
        if progress > 0.55 && fitting_bins_count > 0 {
            score += 55.0 * progress;
        }
        // Never open a new bin for small items when many bins can host them.
        if fitting_bins_count > 3 && isz < 0.25 * cap {
            score += 45.0;
        }
        // Extra consolidation pressure: if the next item could still fit the
        // fresh bin after this one, opening is slightly more attractive only
        // when existing fits are loose.
        if fitting_bins_count > 0 && next_item_size as f64 <= pr {
            score += 12.0 * (1.0 - pr / cap);
        }
    }

    // Balance toward below-mean residual bins.
    if br < mean_residual {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // normalized post-residual in (0,1]
    let x = pr / cap;

    // Base: prefer smaller post-residual, but with non-linear shaping so that
    // tiny residuals (dead space) are penalized extra via a cubic term.
    let mut score = x * 40.0 - x.powi(3) * 25.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tighter fits matter less; late in the stream, exact fits matter more.
    let progress_coupling = (1.0 - t) * (x - 0.5).powi(2) * 12.0 + t * (1.0 - x).powi(2) * 18.0;
    score += progress_coupling;

    // Exact fit reward (post_residual == 0) scaled smoothly by progress.
    if pr == 0.0 {
        score -= 10.0 + 20.0 * t;
    }

    // Last-chance bin: strongly reward if it's the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement;
    // if the next item is large and post-residual is small, slight penalty.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 6.0 * (1.0 - (ni / (pr + 1.0))).powi(2);
        } else {
            score += 4.0 * ((ni - pr) / cap);
        }
    }

    // Mild pressure toward consolidating into fewer bins.
    score += (open_bins_count as f64) * 0.05;

    // Mean-residual deviation: prefer bins whose residual is near the mean
    // (balanced packing), via smooth quadratic term.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0;

    // New-bin candidate handling: an empty bin has high post-residual; the cubic
    // shaping above keeps it unattractive unless all fits are poor. Add a smooth
    // late-stream penalty on opening new bins.
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let mut score = pr;

    // Perfect closure: best possible outcome.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    let tightness = item_size as f64 / br.max(1.0);
    score -= 25.0 * tightness;

    // Open-bin pressure.
    score += 4.0 * open_bins_count as f64;

    // Prefer tighter-than-mean bins.
    if br < mean_residual {
        score -= 6.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: exact chain with next item is gold.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx;
            score -= 250.0 * (1.0 - fill_after_next / cap);
            score += 0.4 * fill_after_next;
            let dev = (fill_after_next - mean_residual).abs();
            score -= 12.0 * (1.0 - dev / cap).max(0.0);
            if fill_after_next == 0.0 {
                score -= 150.0;
            }
            if fill_after_next > 0.0 && fill_after_next < nx * 0.25 {
                score += 40.0;
            }
            if fill_after_next > 0.0 && fill_after_next >= nx * 0.25 && fill_after_next <= nx * 0.6 {
                score -= 18.0;
            }
            if fill_after_next > 0.0 && fill_after_next <= 8.0 {
                score -= 25.0;
            }
            // Two-step chain: item + next fills bin almost exactly.
            if (item_size as f64 + nx) / br > 0.92 {
                score -= 20.0;
            }
        } else {
            // dead space relative to known next item
            score += 0.6 * pr + 50.0;
            if next_item_size <= bin_residual {
                score += 8.0;
            }
            if next_item_size > bin_residual && br < nx * 0.5 {
                score += 30.0 * (1.0 - pr / cap);
            }
            if fitting_bins_count > 2 && br > nx * 0.75 {
                score += 15.0 * (br / cap);
            }
            if fitting_bins_count <= 2 {
                let dev = (pr - mean_residual).abs();
                score += 0.8 * dev;
            }
            // Penalize large residual relative to next item need.
            if pr > nx * 1.5 {
                score += 0.5 * (pr - nx * 1.5);
            }
        }
    }

    // New-bin candidate handling: fresh bin only attractive for large items.
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity / 2 {
            score -= 5.0;
        } else {
            score += 20.0 + 3.0 * open_bins_count as f64;
        }
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
        // Late in the stream, opening a fresh bin is riskier.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Slight stream-progression bias against wasteful residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that lie in "useful" residue
    // classes modulo common small item sizes (items 1..100, so mod classes 2..10 matter).
    if post_residual > 0 {
        let mut harmonic_bonus = 0.0f64;
        for m in 2..=10u32 {
            if post_residual % m == 0 {
                // residual divisible by m -> future items of size m tile it perfectly
                harmonic_bonus += (bin_capacity as f64 / m as f64) * 0.5;
            }
        }
        score -= harmonic_bonus;
    } else {
        // perfect fit: strong reward
        score -= 200.0;
    }

    // Dead-space penalty: small nonzero residuals are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // chain fit
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            if npr % 5 == 0 || npr % 10 == 0 {
                score -= 40.0;
            }
            score += npr as f64 * 0.3;
        } else {
            // next item cannot go here regardless; mild penalty
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Waste-avoidance: placing into a tight bin (small residual) is efficient
    let tightness = (bin_residual as f64) / (bin_capacity as f64);
    score += tightness * 30.0;

    // Fractional capacity thresholds on item_size via integer division
    let q = item_size / 10;
    match q {
        1..=3 => score -= 5.0,   // small items: flexible, mild reward
        7..=10 => score -= 10.0, // large items: place them while possible
        _ => {}
    }

    // New-bin candidate handling: only open a new bin when current bin would leave
    // bad dead space and mean residual is already low
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual > 0 && post_residual < 15;
        if bad_fit && mean_residual < 20.0 && open_bins_count > 0 {
            score -= 100.0 + 50.0 * (1.0 - progress);
        } else {
            score += 120.0; // default: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
