pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 45.0; // dead space below min item size
    } else if post_residual < 20 {
        score += 18.0;
    } else {
        // Larger leftovers are more reusable; mild reward proportional to size.
        score -= pr * 0.15;
    }

    // Tightness reward: how much of the bin the item consumes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item could reuse the post residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size <= bin_residual {
            // next item fits here but current placement would block it: penalty
            score += 8.0;
        }
    }

    // New-bin candidate: make it attractive only when open bins are fragmented
    // (mean residual low) or the item is large.
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 5.0 + fragmentation * 20.0 + fill_ratio * 10.0;
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
