pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect chain: this bin will be exactly filled next step
        } else if next_item_size <= post_residual {
            // next item still fits here: partial chain bonus, scaled by how well it fills
            score -= 25.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // next item cannot follow into this bin: penalize leftover dead space
            score += 10.0;
        }

        // reward item_size + next_item_size jointly filling the bin
        let pair = item_size as f64 + nxt;
        if (bin_capacity as f64 - pair).abs() < 0.5 {
            score -= 80.0;
        }
    }

    // Compare against mean residual: bins with residual near/below mean are good targets
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 8.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 5.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 20.0; // fresh bin allows a clean 2-item pairing
        } else {
            score += 45.0; // discourage opening new bins otherwise
        }
    }

    // Late in stream: consolidate into existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 12.0 * (bin_residual as f64 / bin_capacity as f64);

    // Slight preference for fewer open bins (avoid bin fragmentation)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
