pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual (subtract more for snug placement)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;

    // Penalize dead space: post residual that is too small to hold any future item
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 {
        // reward leaving usable residual, but not too much
        score -= 2.0 * (post_residual as f64 / bin_capacity as f64).sqrt();
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if we waste a big bin on this item
            score += 3.0 * fit_ratio;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Pressure from many open bins: prefer filling existing bins when bin count is high
    let bin_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * 8.0;
    if bin_residual < bin_capacity {
        score -= bin_pressure;
    } else {
        // new-bin candidate: penalize opening new bins unless fit is poor or bins scarce
        score += 10.0 * (1.0 - fit_ratio) + bin_pressure * 0.5;
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Time horizon: early in stream, be conservative (favor new bins for flexibility);
    // late in stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
