        score -= 6.0 * progress;
    } else {
        score += 6.0 * progress;
    }

    // Global residual alignment: prefer bins whose residual is close to the mean residual
    let dev = (bin_residual as f64 - mean_residual).abs();
    if bin_residual < bin_capacity {
        score += 0.05 * dev;
    }

    // Waste-avoidance: penalize leaving residual that no plausible item (>=1) can pair with next
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

