                score += 30.0 * (1.0 - pr / cap) ;
            }
            // dead-space penalty scaled by residual share when alternatives exist
            if fitting_bins_count > 2 && br > nx * 0.75 {
                score += 15.0 * (br / cap) ;
            }
            // few alternatives: penalize deviation from mean residual and large waste
            if fitting_bins_count <= 2 {
                let dev = (pr - mean_residual) . abs () ;
                score += 0.8 * dev ;
                if br > nx && pr > 0.35 * cap { score += 22.0 * (pr / cap) ; }
