pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; late in the stream, strongly prefer
    // minimizing leftover space since future opportunities shrink.
    let coupling = post * post / cap * (0.5 + progress);
    score += 0.8 * coupling;

    // Reward filling bins deeply (post_residual near zero), with a smooth
    // cubic saturation term.
    let fill = 1.0 - post / cap;
    score -= 4.0 * fill * fill * fill;

    // Dead-space penalty: residual that is too small to fit even a tiny item
    // (sizes >= 1) is only penalized lightly, but residual just below typical
    // item sizes is wasted; penalize smoothly via a sine-shaped trough.
    let waste = post / cap;
    score += 3.0 * (std::f64::consts::PI * waste).sin().abs() * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + progress);
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 5.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving a large awkward gap.
        score += 2.0 * post / cap * (1.0 - progress);
    }

    // New-bin candidate handling: an empty bin has large post_residual; add a
    // moderate penalty so it is chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    // Mild preference to balance residuals across open bins.
    score += 0.3 * (post - mean_residual).abs() / cap;

    score
}

