pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod small integers
    // capture "how divisible the leftover space is" by typical item sizes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by common item sizes -> very reusable.
    let mut divisibility_bonus = 0.0;
    for &d in &[10u32, 20, 25, 50] {
        if post_residual >= d && post_residual % d == 0 {
            divisibility_bonus += 6.0;
        }
    }
    score -= divisibility_bonus;

    // Class B: small dead space (waste) is heavily penalized non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post as f64 / 10.0);
    }

    // Class C: perfect fit reward, stronger as stream progresses.
    if post_residual == 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead coupling: does post_residual fit next_item_size?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            // Exact match for next item is excellent.
            if post_residual == next_item_size {
                score -= 35.0;
            } else {
                // Harmonic: leftover after hypothetically placing next item.
                let after_next = post_residual - next_item_size;
                if after_next < 10 {
                    score += 8.0; // leaves tiny dead space after next
                } else {
                    score -= 10.0 * (1.0 - (after_next as f64 / cap).min(1.0));
                }
            }
        } else {
            // Bin can't host next item: penalize proportionally to next size.
            score += 5.0 + 0.1 * n;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins with high mean residual: prefer consolidating into
    // bins below the mean residual (tighter bins) to free others.
    if open_bins_count > 1 {
        let diff = mean_residual - post;
        score += 0.15 * diff; // lower post_residual than mean -> favored
    }

    // New-bin candidate: prefer it only when no open bin fits well,
    // i.e. discourage opening new bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let urgency = if fitting_bins_count == 0 { 0.0 } else { 15.0 + 20.0 * (1.0 - progress) };
        score += urgency;
    }

    // Mild preference for filling bins that are already half empty or less.
    let fill_frac = 1.0 - bin_residual as f64 / cap;
    score -= 5.0 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    if post_residual > 0 {
        let min_useful = 10u32.min(bin_capacity); // smallest plausible future item footprint
        if post_residual < min_useful {
            // gap below the smallest item -> pure dead space
            score += 60.0 * (min_useful as f64 - post_residual as f64 + 1.0);
        } else {
            // small gaps are less valuable than large gaps; superlinear penalty
            let gap = post_residual as f64;
            score += 25.0 / gap; // tiny gaps get big penalty, large gaps ~0
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that still leave room for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // creates a gap the next item cannot use -> extra penalty
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity, post_residual high,
    //  so adding open_bins_count pressure raises its score further).
    score += open_bins_count as f64 * 2.0;

    // Early in the stream, be slightly more willing to spread items (better future packing)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 8.0 * (mean_residual / bin_capacity.max(1) as f64);

    // Prefer bins tighter than the current mean residual (consolidation)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

