pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good.
    if post_residual == 0 {
        score -= 60.0; // perfect fit closes the bin
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // chain of two perfect fits
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 25.0 - slack * 1.5; // next item fits snugly
            } else {
                score += slack * 0.15; // leftover after next item is waste
            }
        } else {
            // next item cannot fit here; the leftover is potential dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Penalize creating dead space relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 {
        score += (mean_residual * 0.5 - pr) * 0.4;
    } else if pr > mean_residual * 1.5 {
        score -= (pr - mean_residual * 1.5) * 0.1;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + (bin_residual - item_size) as f64 * 0.2;
    }

    // New-bin candidate: prefer it only when the stream is early (more future items)
    // and current fit is poor; otherwise penalize opening extra bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + progress * 25.0; // late in stream, keep using open bins
        if fitting_bins_count > 0 {
            score += 20.0; // an open bin can already fit: strongly prefer it
        }
    }

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

