    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer closing bins.
        score -= 80.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.25 * item_size as f64;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // (large post_residual) or no real bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a new bin when many bins are open and fragmented.
        score -= 2.0 * (open_bins_count as f64).sqrt();
        // Cheaper when mean residual is high (existing bins are too full to be useful).
        score -= 0.30 * mean_residual;
        // Discourage opening new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
        // A fresh bin is great if the next item is large and would fit well.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Mild penalty for leaving residuals that few items could use (odd dead zones).
    if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Prefer spreading across bins when many open bins exist (balance residuals).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let mut score = pr ;
    if post_residual == 0 { score -= 900.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if next_item_size == post_residual {
            score -= 700.0 ;
        } else if next_item_size < post_residual {
            let fill_after_next = pr - nx ;
            score -= 250.0 * (1.0 - fill_after_next / cap) ;
            score += 0.4 * fill_after_next ;
            let dev = (fill_after_next - mean_residual) . abs () ;
            score -= 12.0 * (1.0 - dev / cap) . max (0.0) ;
            if fill_after_next == 0.0 { score -= 150.0 ; }
            if fill_after_next > 0.0 && fill_after_next < nx * 0.25 { score += 40.0 ; }
            if fill_after_next > 0.0 && fill_after_next >= nx * 0.25 && fill_after_next <= nx * 0.6 {
                score -= 18.0 ;
            }
            if fill_after_next > 0.0 && fill_after_next <= 8.0 { score -= 25.0 ; }
        } else {
            score += 0.6 * pr + 50.0 ;
            if next_item_size <= bin_residual { score += 8.0 ; }
            if next_item_size > bin_residual && bin_residual < nx * 0.5 {
                score += 30.0 * (1.0 - pr / cap) ;
            }
            if fitting_bins_count > 2 && br > nx * 0.75 {
                score += 15.0 * (br / cap) ;
            }
            if fitting_bins_count <= 2 {
                let dev = (pr - mean_residual) . abs () ;
                score += 0.8 * dev ;
            }
        }
    }
    // tighter-fit preference scaled by scarcity of alternatives
    let tight = (br - pr) as f64 ;
    score += 0.05 * tight ;
    if fitting_bins_count <= 2 { score += 0.05 * tight ; }
    // discourage opening a new bin when a decent fit exists
    if bin_residual == bin_capacity {
        let nx = if next_item_size > 0 { next_item_size as f64 } else { 0.0 } ;
        let waste_pressure = (mean_residual / cap).clamp (0.0 , 1.0) ;
        score += 20.0 + 35.0 * waste_pressure ;
        if fitting_bins_count > 0 && nx > 0.0 && nx <= mean_residual {
            score += 25.0 ;
        }
        // extra pressure when many open bins can still absorb items
        if fitting_bins_count >= 3 { score += 12.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post residual, with smooth non-linear shaping.
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, moderately large residuals are tolerable; late, dead space is costly.
    let prn = pr / cap; // normalized post residual in [0,1]
    let phase = 0.5 + 0.5 * progress; // smooth 0.5 -> 1.0 ramp
    score += 30.0 * phase * prn * prn;        // quadratic dead-space penalty grows over stream
    score -= 10.0 * (1.0 - phase) * prn * (1.0 - prn); // early reward for mid-range fills

    // Perfect / near-perfect fit bonus (smooth, no hard cutoffs).
    let tightness = (1.0 - prn).powi(3);
    score -= 25.0 * tightness;

    // Lookahead coupling: reward residual that can still host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack * slack); // next item fits afterwards
        } else {
            let gap = (nx - pr) / cap;
            score += 20.0 * gap * gap; // dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize so we only open when fits are truly poor.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 60.0 + 30.0 * congestion + 20.0 * (1.0 - progress);
        // Allow new bin late in stream if it would be very tight with the item.
        score -= 55.0 * tightness * phase;
    }

    // Mild tie-break toward bins below mean residual (consolidation).
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}
